WITH payload AS (SELECT $archive_payload$[{"id":"8b3563c6-71db-5020-8de0-5260675d54c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -إقرار -طلب إمهال ورفض صاحب احلق -ثبوت الدعوى -إلزام برد املختلس .","document_number":"33462429","case_number":"33611429","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/22","year":"1434","subject":"مطالبة برد مختلس -اختاس مبلغ مالي عن طريق خيانة األمانة -إقرار -طلب إمهال ورفض صاحب احلق -ثبوت الدعوى -إلزام برد املختلس .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/22 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33462429 :‬‬\n                    ‫َر ْق ُم الدعوى‪33611429 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3446845‬تاريخه‪1434/2/25 :‬هـ‬\n\n\n ‫مطالبــة بــرد مختلــس ‪ -‬اختــاس مبلــغ مالــي عــن طريــق خيانــة‬\n ‫األمانــة ‪ -‬إقــرار ‪ -‬طلــب إمهــال ورفــض صاحــب احلــق ‪ -‬ثبــوت الدعــوى‬\n                                               ‫‪ -‬إلــزام بــرد املختلــس ‪.‬‬\n\n\n\n\n ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                          ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n ‫ادعــى وكيــل املدعــي علــى احلاضــر معــه بأنــه إبـاَّن عملــه لــدى موكلــه‬\n ‫قــام بخيانــة األمانــة وذلــك باختــاس مبالــغ ماليــة كانــت يف عهدتــه‬\n ‫وتســببه بحصــول عجــز فيهــا‪ ،‬ولــذا فقــد طلــب إلزامــه بإعــادة املبالــغ‬\n ‫التــي اختلســها إلــى موكلــه ‪ -‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى‬\n ‫وكيــل املدعــي جملــة وتفصيــا‪ -‬قضــت احملكمــة بنــاء علــى إقــرار‬\n ‫املدعــى عليــه بإلزامــه بتســليم املدعــي أصالــة املبلــغ املدعــى بــه ‪ -‬عــارض‬\n ‫املدعــى عليــه علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                   ‫علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪350‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة العامة مبحافظة‬\n      ‫اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة باخلرج‪/‬املكلــف برقــم ‪ 33611429‬وتاريــخ ‪ 1433/10/18‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331843067‬وتاريــخ ‪1433/10/18‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافــق‪ 1433/11/22‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n      ‫‪ 09‬وفيهــا حضــر ‪ ..... /‬ســعودي بالســجل املدنــي رقــم بصفتــه الوكيــل‬\n      ‫الشــرعي عــن والــده ‪ /‬بصفتــه صاحــب مؤسســة ‪ /‬التجاريــة وذلــك‬\n      ‫مبوجــب الوكالــة رقــم ‪ 25591‬يف ‪1430/5/11‬ه ـ الصــادرة مــن كتابــة‬\n      ‫عــدل الدمــام الثانيــة والتــي جعــل للوكيــل الشــرعي فيهــا حــق املرافعــة‬\n      ‫واملدافعــة واملخاصمــة والصلــح والتنــازل وغيــر ذلــك وادعــى على احلاضر‬\n      ‫معــه ‪ /‬ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم مصدرهــا الدمــام‬\n      ‫ا يف حتريــر دعــواه إن املدعــى عليــه‬\n                                            ‫والتــي تنتهــي يف ‪1434/2/1‬ه ـ قائـ ً‬\n      ‫هــذا احلاضــر كان يعمــل لــدى مؤسســة موكلــي مبســمى مديــر فــرع‬\n      ‫اخلــرج ومســؤو ًال عــن املســتودع يف الفــرع نفســه وقــد ُوجــد عجــز يف عهــدة‬\n      ‫املدعــى عليــه حتــت بنــد املبيعــات والتحصيــل وعهــدة املخــزون وعهــدة‬\n      ‫العمــاء مببلــغ قــدره مائــة وســتة عشــر ألفـ ًا ومائــة وســتة وأربعــون ريــا ًال‬\n      ‫وقــد ســبق أن نظــرت الدعــوى ضــد املدعــى عليــه يف احلــق العــام وصــدر‬\n      ‫منكــم القــرار الشــرعي رقــم ‪ 33389167‬يف ‪1433/8/21‬ه ـ والــذي‬\n      ‫ثبــت فيــه إدانــة املدعــى عليــه بخيانــة األمانــة والتســبب يف حصــول عجــز‬\n      ‫يف عهدتــه لــدى املؤسســة التــي يعمــل بهــا مقــداره مائــة وســتون ألف ـ ًا‬\n      ‫وســتة وأربعــون ريــا ًال واحلكــم بتغريــره للحــق العــام بســجنه ملــدة خمســة‬\n\n‫‪351‬‬\n\f‫أشــهر حتتســب منهــا مــدة إيقافــه الســابقة وجلــده ســتني جلــدة علنـ ًا وأنــا‬\n‫اآلن اطلــب إلــزام املدعــى عليــه بــأن يدفــع ملوكلــي املبلــغ الــذي اختلســه‬\n‫والــذي كان يف عهدتــه أثنــاء عملــه مديــر ًا لفــرع املؤسســة باخلــرج وقــدره‬\n‫مائــة وســتون ألف ـ ًا ومائــة وســتة وأربعــون ريــا ًال هكــذا ادعــى وبســؤال‬\n‫املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي وكالــة مــن أننــي كنــت‬\n‫أعمــل لــدى مؤسســة موكلــه وكنــت مديــر ًا لفــرع املؤسســة مبحافظــة‬\n‫اخلــرج ومســئوال عــن املســتودع يف الفــرع وأنــه حصــل بعهدتــي عجــز حتــت‬\n‫بنــد املبيعــات والتحصيــل وعهــدة املخــزون وعهــدة العمــاء مببلــغ مائــة‬\n‫وســتة عشــر ألف ـ ًا ومائــة وســتة وأربعــن ريــا ًال وأنــه قــد صــدر حكــم‬\n‫منكــم بإدانتــي بخيانــة األمانــة والتســبب يف حصــول عجــز يف عهدتــي‬\n‫أثنــاء عملــي يف مؤسســة املدعــي أصالــة مبقــدار مائــة وســتون ألفـ ًا وســتة‬\n‫وأربعــون ريــا ًال فهــذا كلــه صحيــح وأنــا أقــر بدعــوى املدعــي وكالــة‬\n‫ا وال مانــع عنــدي مــن أن أدفــع للمدعي أصالــة املبلغ الذي‬       ‫جملــة وتفصيـ ً‬\n‫يدعــي بــه وقــدره مائــة وســتون ألفـ ًا ومائــة وســتة وأربعــون ريــا ًال لكننــي‬\n‫اطلــب مــن املدعــي وكالــة أن ميهلنــي لســداد هــذا املبلــغ ملــدة شــهر حتــى‬\n‫تاريــخ ‪1433/12/22‬ه ـ هكــذا أجــاب وبعــرض مــا طلبــه املدعــى عليــه‬\n‫مــن مهلــة للســداد علــى املدعــي وكالــة قــال لــن أمهلــه للســداد واطلــب‬\n‫احلكــم عليــه بدفــع املبلــغ حــا ًال لكــون املدعــى عليــه قــد خــان األمانــة‬\n‫ولــذا اطلــب احلكــم عليــه باملبلــغ حــا ًال هكــذا أجــاب وقــد جــرى منــي‬\n‫االطــاع علــى املعاملــة املتعلقــة بهــذه القضيــة التــي ســبق نظرهــا يف‬\n‫احلــق العــام كمــا جــرى منــي االطــاع علــى القــرار الشــرعي الصــادر‬\n‫منــا برقــم ‪ 33389167‬يف ‪1433/8/21‬ه ـ فــإذا هــو يتضمــن إثبــات ادانــة‬\n‫املدعــى عليــه بخيانــة األمانــة والتســبب يف حصــول عجــز يف عهدتــه لــدى‬\n\n\n                                                                                        ‫‪352‬‬\n\f      ‫املؤسســة التــي يعمــل بهــا مقــداره مائــة وســتون ألفـ ًا ومائــة وســتة وأربعون‬\n      ‫ريــا ًال فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة واعتــراف املدعــى عليــه‬\n      ‫مبــا يف ذمتــه للمدعــي أصالــة وملــا تضمنــه القــرار الشــرعي الصــادر منــا‬\n      ‫يف احلــق العــام رقــم ‪ 33389167‬يف ‪1433/8/21‬ه ـ لــذا فقــد حكمــت‬\n      ‫علــى املدعــى عليــه أن يدفــع للمدعــي أصالــة املبلــغ املدعــى بــه وقــدره‬\n      ‫مائــة وســتون ألف ـ ًا ومائــة وســتة وأربعــون ريــا ًال وبعــرض احلكــم علــى‬\n      ‫املدعــى عليــه قــرر عــدم قناعتــه باحلكــم وطلــب االســتئناف واســتعد‬\n      ‫بتقــدمي الئحتــه االعتراضيــة فجــرى تســليمه نســخه مــن احلكــم وأفهــم‬\n      ‫أن مــدة االعتــراض عليــه ثالثــن يوم ـ ًا تبــدأ مــن هــذا اليــوم وأنــه اذا لــم‬\n      ‫يتقــدم باعتراضــه خــال هــذه املــدة فــإن احلكــم يكتســب القطعيــة‬\n      ‫ففهــم ذلــك ووقــع عليــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                      ‫محمــد حــرر يف ‪1433/11/22‬ه ـ ‪.‬‬\n\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3446845‬وتاريــخ‬\n                                                     ‫‪1434/2/25‬هــ‪.‬‬\n\n\n\n\n‫‪353‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":350,"source_page_end":353,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"39156bfb4574e3590d15dff041c15f2ebe9b6496f296a33393bb27acab9734e5","normalized_text_hash":"b035bd676b6ffe0e98033377c69745a55ff4481ba9e8d2702b500a5999ceb831","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p350-33462429"},{"id":"f6bdc5c6-71e2-5537-a61d-2d9dbca4414d","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبلغ مالي يف عهدته عن طريق خيانة األمانة -اإلقرار من املدعى عليه باملبلغ -احلكم بالزام املدعى عليه بدفع املبلغ املدعى به .","document_number":"3454717","case_number":"33683795","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"رد مختلس -اختاس مبلغ مالي يف عهدته عن طريق خيانة األمانة -اإلقرار من املدعى عليه باملبلغ -احلكم بالزام املدعى عليه بدفع املبلغ املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/3/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3454717 :‬‬\n                   ‫َر ْق ُم الدعوى‪33683795 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34255296‬تاريخه‪1434/7/1 :‬هـ‬\n\n\n‫رد مختلــس ‪ -‬اختــاس مبلــغ مالــي يف عهدتــه عــن طريــق خيانــة‬\n‫األمانــة ‪ -‬اإلقــرار مــن املدعــى عليــه باملبلــغ ‪ -‬احلكــم بالــزام املدعــى‬\n                                           ‫عليــه بدفــع املبلــغ املدعــى بــه ‪.‬‬\n\n\n\n\n                                    ‫‪ .1‬من أقر بحق آلدمي لزمه ما أقر به‪.‬‬\n‫‪ .2‬مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة‬\n                                                        ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــي علــى احلاضــر معــه بأنــه إبـاَّن عملــه لــدى موكلــه‬\n‫قــام بخيانــة األمانــة وذلــك باختــاس مبالــغ ماليــة كانــت يف عهدتــه‬\n‫وتصرف فيها لصالح نفســه ‪ ،‬طلب إلزامه بإعادة املبالغ التي اختلســها‬\n‫إلــى موكلــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف الدعــوى وأقــر أن بذمتــه‬\n‫مبلــغ عبــارة عــن قرضــة حســنة ‪ ،‬قــدم وكيــل املدعــي إقــرارا للمدعــى‬\n‫عليــه باختــاس جــزء مــن املبلــغ املدعــى بــه فأقــر بصــدوره منــه ودفــع‬\n‫بــأن شــريك املدعــي تنــازل عــن هــذا املبلــغ إال أنــه عجــز عــن إثبــات هــذا‬\n‫الدفــع وأقــر مببلــغ إضــايف يف ذمتــه للمدعــي ‪ ،‬أدى الشــريك املذكــور‬\n‫بعــد إدخالــه يف الدعــوى اليمــن علــى نفــي مــا دفــع بــه املدعــى عليــه ‪،‬‬\n                                                                                       ‫‪354‬‬\n\f      ‫عجــز وكيــل املدعــي عــن إثبــات باقــي املبلــغ املدعــى بــه وأدى املدعــى‬\n      ‫عليــه اليمــن علــى نفــي الدعــوى باملبلــغ املتبقــي ‪ -‬قضــت احملكمــة‬\n      ‫بنــاء علــى إقــرارات املدعــى عليــه بإلزامــه بتســليم املدعــي أصالــة املبلــغ‬\n      ‫املدعــى بــه ســوى مــا عجــز املدعــي عــن إثباتــه منــه ‪ -‬قنــع املدعيــان‬\n      ‫باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف‬\n                                                              ‫املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بينبــع‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بينبع‪/‬املســاعد برقــم ‪ 33683795‬وتاريــخ ‪ 1433/11/30‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332152945‬وتاريــخ ‪ 1433/11/30‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/01/14‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 00‬‬\n      ‫وفيهــا حضــر املدعــي ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫الوكيــل الشــرعي عــن ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫بالوكالــة رقــم ‪ 33384203‬يف ‪1433/11/16‬ه ـ الصــادرة مــن كتابــة‬\n      ‫عــدل اجلبيــل واملخــول لــه فيهــا بالبيــع والشــراء واإلفــراغ وقبولــه واســتالم‬\n      ‫الثمــن وتســليم املثمــن والتأجيــر واســتالم األجــرة وتوقيــع العقــود اخلاصــة‬\n      ‫مبــا ذكــر واملداعــاة واملخاصمــة وســماع الدعــاوي والــرد عليهــا واقامــة‬\n      ‫البينــة وقبــول احلكــم واالعتــراض عليــه وقــرر املدعــي قائــا إن املدعــى‬\n      ‫عليــه قــام باختــاس مبلــغ وقــدره أربعــة وســتون ألفــا وأربعمائــة وثمانيــة‬\n      ‫وســبعون ريــاال مــن شــركة موكلــي شــركة ‪ ...‬وهــي كالتالــي األول‬\n      ‫مبلــغ وقــدره واحــد وأربعــون ألفــا وأربعمائــة وثمانيــة وســبعون ريــاال‬\n\n‫‪355‬‬\n\f‫والثانــي ثالثــة وعشــرون ألفــا أطلــب احلكــم عليــه وإلزامــه بإعــادة هــذه‬\n‫املبالــغ ملوكلــي هــذه دعــواي وبســؤال املدعــى عليــه عمــا ذكــره املدعــي‬\n‫أجــاب قائــا بــأن مــا ذكــره املدعــي غيــر صحيــح والصحيــح أن ملوكلــه‬\n‫بذمتــي مبلــغ وقــدره تســعة آالف ريــال قرضــة حســنة هكــذا أجــاب‬\n‫وبطلــب البينــة مــن املدعــي أبــرز إقــرارا بتوقيــع املدعــى عليــه وهــذا نصــه‬\n‫(أقــر أنــا املوقــع والباصــم أدنــاه الســيد ‪ ...‬إقامــة مينــي بأننــي قــد قمــت‬\n‫بالتصــرف مببالــغ تخــص شــركة وشــريكه للخدمــات التجاريــة ســجل‬\n‫جتــاري رقم‪...‬ومالكهــا يشــار لهــا يف هــذا اإلقــرار بالشــركة بأغــراض‬\n‫شــخصية لــي وبغيــر حــق أو إذن مســبق مــن الشــركة وبنــاء علــى ذلــك‬\n‫يحــق للشــركة مطالبتــي بســداد هــذه املبالــغ حــاال وإحالــة املوضــوع إلــى‬\n‫اجلهــات املختصــة التخــاذ اإلجــراءات الالزمــة لضمــان إعــادة هــذه املبالــغ‬\n‫للشــركة ولكننــي أطلــب مــن الشــركة إعطائــي مهلــة لســداد هــذه‬\n‫املبالــغ يف أقــرب وقــت ممكــن وأرجــو أن توافــق الشــركة علــى ذلــك‬\n‫وإعالمــي خطيــا باملهلــة والطريقــة للســداد علمــا بــأن املبالــغ التــي قمــت‬\n‫بالتصــرف بهــا كمــا ذكــرت باألعلــى هــي كالتالــي ‪ -1‬مبلــغ وقــدره‬\n‫اثنــا عشــر ألــف وســتمائة ريــال عبــارة عــن دخــل مبيعــات للشــركة قمــت‬\n‫بإضاعتــه‪ -2 .‬مبلــغ وقــدره ســتة عشــر ألــف وســبعمائة وثمــان وســبعون‬\n‫ريــال عبــارة عــن دخــل مبيعــات للشــركة قمــت بصرفهــا علــى أغــراض‬\n‫شــخصية لــي‪ -3 .‬مبلــغ وقــدره ســبعة آالف ومائــة ريــال عبــارة عــن جــزء‬\n‫اثنــا عشــر ألــف وخمســمائة ريــال مت حتويلــه مــن حســاب الشــركة إلــى‬\n‫حســابي الشــخصي لدفــع قيمــة أعمــال مقاولــة للشــركة ولكــن قمــت‬\n‫بصرفهــا علــى أغــراض شــخصية لــي‪ -4 .‬مبلــغ وقــدره خمســة آالف ريــال‬\n‫عبــارة عــن مبلــغ ســلفة شــخصية علــى الراتب)ا‪.‬ه ـ وبعــرض هــذا اإلقــرار‬\n\n\n                                                                                        ‫‪356‬‬\n\f      ‫علــى املدعــى عليــه قــال إن اإلقــرار صحيــح ولكــن الشــركة تنازلت عن‬\n      ‫هــذا املبلــغ هكــذا أجــاب وبطلــب البينــة مــن املدعــى عليــه عــن تنــازل‬\n      ‫الشــركة قــال إنــه مت التنــازل شــفهيا بينــي وبــن املديــر العــام للشــركة‬\n      ‫وبطلــب البينــة مــن املدعــي علــى أن املدعــى عليــه اختلــس مبلــغ ثالثــة‬\n      ‫وعشــرين ألــف ريــال قــال أطلــب إعطائــي مهلــة لذلــك فأجيــب لطلبــه‬\n      ‫كمــا طلبــت منــه أيض ـ ًا إحضــار الشــريك الثانــي وهــو فاســتعد بذلــك‬\n      ‫ولــذا رفعــت اجللســة ويف يــوم األربعــاء املوافــق‪ 1434/01/28‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه‬\n      ‫وجــرى ســؤال املدعــي عــن بينتــه فقــال أطلــب إعطائــي مهلــة لذلــك‬\n      ‫فأجيــب لطلبــه وحــدد لهــم موعــد يف يــوم الثالثــاء املوافق‪1434/3/3‬ه ـ‬\n      ‫ويف يــوم الثالثــاء املوافــق‪ 1434/03/03‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة والنصــف صباحــا وفيهــا حضــر املدعي اصاله ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم واملدعــي ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم فســألت املدعــي هــل تنازلــت عــن املدعــى عليــه عــن مبلــغ‬\n      ‫واحــد واربعــن الفــا وأربعمائــة وثمانيــة وســبعني ريــاال فأجــاب بأننــي لــم‬\n      ‫اتنــازل عنــه ومــا ذكــره غيــر صحيــح هكــذا أجــاب وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال أطلــب ميينــه علــى نفــي التنــازل وبعــرض ذلــك علــى‬\n      ‫املدعــي ‪ ...‬حلــف قائــا ( واهلل العظيــم الــذي ال الــه اال هــو عالــم الغيــب‬\n      ‫والشــهادة اننــي لــم اتنــازل عــن مبلــغ واحــد واربعــن الفــا واربعمائــة‬\n      ‫وثمانيــة وســبعني ريــاال واملفصــل بإقــرار املدعــى عليــه املذكــور اعــاه‬\n      ‫وال عــن جــزء منــه ومــا ذكــره املدعــى عليــه مــن التنــازل غيــر صحيــح )‬\n      ‫هكــذا اجــاب فســألت املدعــي عــن املبلــغ الثالثــة والعشــرين الــف ريــال‬\n      ‫التــي ادعــى بهــا املدعــي فقــال مــا ذكــره املدعــي غير صحيــح والصحيح‬\n\n\n‫‪357‬‬\n\f‫ان املبلــغ اثنــا عشــر الــف ريــال فقــط فســألت املدعــي هــل لديــك بينــه‬\n‫علــى املبلــغ األحــد عشــر الــف ريــال املتبقــي مــن الثالثــة والعشــرين الــف‬\n‫ريــال فقــال ال ونطلــب ميينــه وبعــرض ذلــك علــى املدعــى عليــه وافــق علــى‬\n‫ذلــك فحلــف قائــا ( واهلل العظيــم الــذي ال الــه اال هــو عالــم الغيــب‬\n‫والشــهادة ان املبلــغ الــذي أخذتــه هــو مبلــغ اثنــا عشــر الــف ريــال وليــس‬\n‫ثالثــة وعشــرين الــف ريــال كمــا يدعــي املدعيــان ) هكــذا حلــف وبنــاء‬\n‫علــى مــا ســبق مــن الدعــوى واإلجابــة ومبــا ان املدعــى عليــه اقــر ان‬\n‫بذمتــه مبلــغ تســعه الــف ريــال قرضــه حســنه ولــم يقــم البينــة علــى تنــازل‬\n‫املدعــي عــن مبلــغ الواحــد واالربعــن الــف وأربعمائــة وثمانيــة وســبعني‬\n‫ريــاال ومبــا ان املدعــي نفــي التنــازل وإلقــرار املدعــى عليــه وميينــه انــه لــم‬\n‫يأخــذ اال مبلــغ اثنــى عشــر الــف ريــال ولــم يقيمــا املدعيــان البينــة علــى مــا‬\n‫ذكــره مــن ان املدعــى عليــه أخــذ مبلــغ ثالثــة وعشــرين الــف ريــال والن‬\n‫مــن أقــر بحــق ادمــي لزمــه مــا أقــر بــه وبهــذا كلــه فقــد حكمــت بــأن‬\n‫يدفــع املدعــى عليــه للمدعيــان مبلــغ وقــدره اثنــان وســتون الفــا وأربعمائــة‬\n‫وثمانيــة وســبعون ريــاال كاملــه حــاال هــذا مــا ظهــر لــي وبــه حكمــت‬\n‫وبعــرض احلكــم علــى املدعيــان قــررا قناعتهمــا بــه كمــا قــرر املدعــى‬\n‫عليــه اعتراضــه بالئحــة اعتراضيــه فأفهــم بــأن لــه مــدة ثالثــن يومــا مــن‬\n‫تاريــخ هــذا اليــوم واذا لــم يقــدم الئحتــه االعتراضيــة خاللهــا فــأن يســقط‬\n‫حقــه مــن االعتــراض ويكتســب احلكــم القطعيــة كمــا جــرى تســليمه‬\n‫صــوره مــن صــك احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/03‬ه ـ ويف يــوم الثالثــاء‬\n‫املوافــق‪ 1434/04/30‬ه ـ افتتحــت اجللســة الســاعة ‪ 08:30‬وفيهــا فقــد‬\n‫اطلعــت علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه ولــم أجــد‬\n\n\n                                                                                           ‫‪358‬‬\n\f      ‫فيهــا مــا يؤثــر علــى مــا حكمــت بــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/30‬ه ـ‬\n      ‫ويف يــوم األحــد املوافــق‪ 1434/06/18‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫العاشــرة فتحــت اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫مالحظــا عليهــا بالقــرار رقــم ‪34225357‬يف‪1434/5/28‬ه ـ وهــذا نــص‬\n      ‫احلاجــة منــه ( وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقرر إعادتها لفضيلة حاكمها ملالحظة أن ‪ -1‬الدعوى يف مبلغ‪64‬ألف‬\n      ‫وأربعمائــة وثمانيــة وســبعني ريــاال ولــم يحكــم إال مببلــغ اثنــن وســتني‬\n      ‫ألــف وأربعمائــة وثمانيــة وســتني ريــاال فلمــاذا؟ ‪ -2‬احلكــم فيــه بعــض‬\n      ‫األخطــاء النحويــة واإلمالئيــة فيعــاد النظــر يف ذلــك ومثــال علــى ذلــك‬\n      ‫لــم يقيمــا املدعيــان وللمدعيــان فيصحــح ذلــك واهلل املوفــق وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم)قاضي اســتئناف د‪.‬‬\n      ‫ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة املــدرع‬\n      ‫ختمــه وتوقيعه)أ‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة حفظهــم اهلل عــن‬\n      ‫مالحظتهــم األولــى بــأن املبلــغ الــذي حكمــت فيــه هو مبلغ اثنان وســتون‬\n      ‫ألفــا وأربعمائــة وثمانيــة وســبعون ريــاال وليــس مبلــغ اثنــن وســتني ألفــا‬\n      ‫وأربعمائــة وثمانيــة وســتني ريــاال وتفصيــل ذلــك كمــا يلــي أوال‪ :‬مبلــغ‬\n      ‫وقــدره واحــد وأربعــون ألفــا وأربعمائــة وثمانيــة وســبعون ريــاال اعتــرف‬\n      ‫فيهــا املدعــى عليــه باعترافــه املــدون يف الصحيفــة األولــى مــن الصــك‪،‬‬\n      ‫ثانيــا‪ :‬مبلــغ وقــدره تســعة آالف ريــال اعتــرف فيهــا املدعــى عليــه بأنــه‬\n      ‫اقتــرض مــن املدعــي أصالــة قرضــة حســنة‪ ،‬ثالثــا‪ :‬مبلــغ وقــدره اثنــا‬\n      ‫عشــر ألــف ريــال وهــو املبلــغ الــذي اعتــرف بــه املدعــى عليــه وحلــف‬\n      ‫عليــه كمــا هــو مبــن يف الصحيفــة الثانيــة مــن الصــك وأمــا مــا ذكــره‬\n\n\n‫‪359‬‬\n\f‫أصحــاب الفضيلــة مــن مالحظتهــم الثانيــة فالصــواب لــم يقــم املدعيــان‬\n‫البينــة وللمدعيــن وعلــى املدعيــن هــذا مــا لــزم اجلــواب عنــه وقــررت‬\n‫بعــث املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/18‬ه ـ‬\n            ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n‫علــى املعاملــة الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة بينبــع‬\n‫برقــم (‪ ) 332152945‬وتاريــخ (‪1434 /6/19‬هــ) املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة الشــيخ ‪ ......... /‬القاضــي باحملكمــة العامــة‬\n‫بينبــع برقــم (‪ )3454717‬وتاريخ(‪1434/3/3‬هــ) ‪ ،‬واملتضمــن دعــوى‬\n‫‪ ............‬ســعودي اجلنســية ضــد ‪ ............ /‬مينــي اجلنســية يف مبلــغ مالــي‬\n‫‪،‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى‬\n                       ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪360‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":354,"source_page_end":360,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0589107ddadd64bfb9f0c7629879853113a91f23b8d4e7fb1ccbf6711e0c4f9a","normalized_text_hash":"4d4664d0639f130b6412efb77d88fd540e0d30f9d344a85df63149d5dbe9f637","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p354-3454717"},{"id":"d74bb39c-9c9e-5fac-8f78-e4310f56c160","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مختلس -مبالغ مالية وقيمة تلفيات -بينة غير موصولة -استعداد املدعي عليه بحلف اليمن على نفي دعوى املدعي -رفض املدعي اليمن من املدعى عليه -احلكم بصرف النظر عن الدعوى .","document_number":"34286925","case_number":"234740804","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/2","year":"1434","subject":"مطالبة برد مختلس -مبالغ مالية وقيمة تلفيات -بينة غير موصولة -استعداد املدعي عليه بحلف اليمن على نفي دعوى املدعي -رفض املدعي اليمن من املدعى عليه -احلكم بصرف النظر عن الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/2 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34286925 :‬‬\n                         ‫َر ْق ُم الدعوى‪234740804 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34353899‬تاريخه‪1434/11/9:‬هـ‬\n\n\n      ‫مطالبــة بــرد مختلــس ‪ -‬مبالــغ ماليــة وقيمــة تلفيــات ‪ -‬بينــة غيــر‬\n      ‫موصولــة ‪ -‬اســتعداد املدعــي عليــه بحلــف اليمــن علــى نفــي دعــوى‬\n      ‫املدعــي ‪ -‬رفــض املدعــي اليمــن مــن املدعــى عليــه ‪ -‬احلكــم بصــرف‬\n                                                      ‫النظــر عــن الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                                 ‫تســبيب احلكــم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى احلاضــر معــه بأنــه َّإبــان عملــه لديــه يف املؤسســتني‬\n      ‫اململوكتــن لــه قــام باختــاس مبالــغ ماليــة عبــارة عــن قيمــة بضائــع‬\n      ‫مــن املــواد الغذائيــة كمــا تســبب يف تلــف بضاعــة مــن احللويــات لــم يقــم‬\n      ‫بتوزيعهــا ‪ ،‬ولــذا فقــد طلــب إلزامــه بــرد قيمــة البضائــع املختلســة إليــه‬\n      ‫مــع إلزامــه بتحمــل اخلســائر الناجتــة عــن ذلــك ‪ ،‬أنكــر املدعــى عليــه‬\n      ‫الدعــوى جملــة وتفصيــا ســوى أنــه يعمــل لــدى املدعــي ‪ ،‬قــدم املدعــي‬\n      ‫عــدد ًا مــن املســتندات إال أنهــا غيــر موصلــة إلثبــات دعــواه ‪ ،‬أفهمــت‬\n      ‫احملكمــة املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه فلــم يقبلها‬\n      ‫‪ ،‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه‬\n\n‫‪361‬‬\n\f‫لهــا وأفهامــه بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه متــى شــاء ‪-‬‬\n‫قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                        ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪234740804‬‬\n‫وتاريــخ ‪1431/08/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3164875‬وتاريــخ‬\n‫‪1431/7/8‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/01/11‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر (‪ ).....‬ســعودي بالســجل رقــم (‪ ).....‬وأدعــى علــى‬\n‫ا يف دعــواه أننــي أملــك‬ ‫احلاضــر معــه (‪ ).....‬باإلقامــة رقــم (‪ ).....‬قائ ـ ً‬\n‫مؤسســة (‪ ).....‬للمقــاوالت ومؤسســة (‪ ).....‬للمــواد الغذائيــة وقــد كان‬\n‫املدعــى عليــه هــذا احلاضــر يعمــل حتــت كفالتــي يف املؤسســتني وقــد‬\n‫اكتشــفت أن املدعــى عليــه قــام باختــاس مبلــغ وقــدره تســعة وســبعون‬\n‫ألــف وخمســمائة واثنــان وعشــرون ريــا ًال قيمــة بضائــع قــام ببيعهــا وهــي‬\n‫عبــارة عــن حلويــات ولــم يقــم بتوريــد قيمتهــا وكذلــك قمــت بتســليمه‬\n‫مبلــغ وقــدره ســتة وخمســون ألــف ومائتــان وخمســون ريــا ًال قيمــة‬\n‫اســتيراد بضاعــة مــن مصنــع للمــواد الغذائيــة مــن دولــة مصــر ولكــن‬\n‫املدعــى عليــه لــم يقــم بتوريدهــا وكذلــك أســتلم قيمــة بضاعــة عبــارة‬\n‫عــن حلويــات وقــد قــام املدعــى عليــه بوضعهــا يف مســتودع ولــم يقــم‬\n‫بتوزيعهــا ممــا أدى إلــى عــدم االســتفادة منهــا وتلفهــا وقــد مت ضبــط‬\n‫هــذه البضاعــة مــن قبــل الشــرطة وتقــدر قيمتهــا بواحــد وســتني ألــف‬\n                                                                                     ‫‪362‬‬\n\f      ‫وأربعمائــة وخمســة وثالثــون ريــا ًال كمــا أطالبــه بقيمــة تكلفــة مشــروع‬\n      ‫لتوريــد املــواد الغذائيــة مــن إيجــار مســتودع ورســوم جمــرك وجتهيــزات‬\n      ‫ورســوم اخلدمــات وذلــك ألن املدعــى عليــه لــم يلتــزم بتوريــد البضاعــة‬\n      ‫التــي طلبتهــا منــه وتقــدر تكلفــة املشــروع مببلــغ وقــدره خمســة وســتون‬\n      ‫ألــف ريــال كمــا أننــي أطالــب املدعــى عليــه بقيمــة تلفيــات لعــدد ثــاث‬\n      ‫ســيارات ســيارتني مــن نــوع (‪ ).....‬وواحــدة مــن نــوع (‪ ).....‬املخصصــة‬\n      ‫للعمــل والتــي اســتخدمها املدعــى عليــه ألغراضــه الشــخصية وتقــدر‬\n      ‫قيمــة التلفيــات بســتني ألــف ريــال أطلــب احلكــم علــى املدعــى عليــه بــأن‬\n      ‫يدفــع لــي مجمــوع هــذه املبالــغ وقدرهــا ثالثمائــة واثنــان وعشــرون ألــف‬\n      ‫ومائتــان وســبعة ريــال هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى‬\n      ‫ا مــا ذكــره املدعــي مــن أننــي كنــت أعمــل معــه فهــذا‬ ‫عليــه أجــاب قائـ ً‬\n      ‫صحيــح ولكننــي لــم أكــن عامــل لديــه وإمنــا كنــت مديــر للمبيعــات وما‬\n      ‫ا‬\n      ‫ذكــره املدعــي مــن مطالبتــه بهــذه املبالــغ فغيــر صحيــح جملـ ًة وتفصيـ ً‬\n      ‫فليــس لــه يف ذمتــي أي شــيء هكــذا أجــاب وبــرده علــى املدعــي أضــاف‬\n      ‫ا الصحيــح مــا ذكرتــه هكــذا أضــاف وبســؤال املدعــي عمــا يثبــت‬        ‫قائـ ً‬\n      ‫صحــة دعــواه أجــاب أطلــب إمهالــي للجلســة القادمــة إلحضــار بيناتــي‬\n      ‫هكــذا أجــاب وعليــه قــررت رفــع اجللســة ويف جلســة أخــرى حضــر‬\n      ‫الطرفــان وبســؤال املدعــي عمــا اســتمهل مــن أجلــه أجــاب أطلــب إمهالــي‬\n      ‫للجلســة القادمــة إلحضــار كامــل بيناتــي علــى دعــواي هكــذا أجــاب‬\n      ‫وعليــه قــررت رفــع اجللســة ويف جلســة أخــرى حضــر الطرفــان وبســؤال‬\n      ‫املدعــي عمــا اســتمهل مــن أجلــه فأجــاب بــأن بينتــي موجــودة ولكــن لــم‬\n      ‫أســتطع إحضارهــا وأطلــب إمهالــي هكــذا أجــاب فجــرى إفهــام املدعــي‬\n      ‫بــأن هــذا اإلمهــال هــو اإلمهــال األخيــر إلحضــار بينتــه ففهــم ذلــك وعليــه‬\n\n\n‫‪363‬‬\n\f‫قــررت رفــع اجللســة ويف جلســة اخــرى حضــر الطرفــان وبســؤال املدعــي‬\n‫عمــا اســتمهل مــن أجلــه أبــرز لنــا عــدد ثالثــة وأربعــن صفحــة تشــتمل‬\n‫علــى عــدد مــن املســتندات جــرى اســتالمها منــه وتســليمها للمدعــى عليــه‬\n‫وأضــاف املدعــى عليــه إن مــا ورد يف جميــع هــذه املســتندات غيــر صحيــح‬\n‫فاملدعــي يدعــي بأننــي اختلســت منــه وال يوجــد يف هــذه املســتندات مــا‬\n‫يثبــت االختــاس أو املبالــغ وإمنــا هــي مجموعــة أوراق ال تثبــت شــيئا وإمنــا‬\n‫هــي دعــوى كيديــة بهــدف األضــرار بــي مــن قبل املدعي هكــذا أضاف‬\n‫وعنــد وصــول القضيــة إلــى هــذا احلــد قــررت رفــع اجللســة ويف جلســة‬\n‫أخــرى حضــر الطرفــان فجــرى ســؤال املدعــي هــل لديــه زيــادة بينــة علــى‬\n‫مــا قــدم أجــاب ليــس لــدي ســوى مــا قدمــت هكــذا أجــاب فجــرى ســؤال‬\n‫املدعــى عليــه هــل هــو مســتعد ببــذل اليمــن علــى نفــي دعــوى املدعــي‬\n‫وانــه لــم يقــم باختــاس املبلــغ املدعــى بــه ولــم يتســبب يف التلفيــات التــي‬\n‫يدعيهــا املدعــي يف دعــواه فأجــاب أننــي مســتعد ببــذل اليمــن علــى نفــي‬\n‫دعــوى املدعــي وأننــي لــم اختلــس أي مبالــغ ولــم أتســبب يف أي تلفيــات‬\n‫ممــا يدعــي بــه املدعــي يف دعــواه هكــذا أجــاب وبســؤال املدعــي هــل‬\n‫يرغــب يف ميــن املدعــى عليــه علــى نفــي دعــواه أجــاب بأننــي ال أرغــب يف‬\n‫ميينــه هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n‫أن املدعــي يطالــب املدعــى عليــه باملبلــغ املدعــى بــه لقــاء اختالســه‬\n‫وتســببه يف التلفيــات التــي ذكرهــا املدعــي يف دعــواه وحيــث ال بينــة‬\n‫موصلــة للمدعــي علــى دعــواه وحيــث أســتعد املدعــى عليــه ببــذل اليمــن‬\n‫علــى نفــي دعــوى املدعــي وحيــث لــم يرغــب املدعــي يف ميــن املدعــى‬\n‫عليــه لــذا فقــد صرفــت النظــر عــن مطالبــة املدعــي للمدعــى عليــه لعــدم‬\n‫اســتحقاقه لهــا وأفهمــت املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي‬\n\n\n                                                                                       ‫‪364‬‬\n\f      ‫دعــواه متــى شــاء وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n      ‫املدعــى عليــه القناعــة واملدعــي عدمهــا وطلــب تدقيــق احلكــم فأجيــب‬\n      ‫لطلبــه فأفهــم باملراجعــة يــوم األربعــاء املوافــق ‪1434/8/3‬ه ـ الســتالم‬\n      ‫نســخه مــن احلكــم لتقــدمي االعتــراض مبوجبهــا خــال ثالثــن يومــا مــن‬\n      ‫تاريــخ األربعــاء ‪1434/8/3‬ه ـ وإذا انتهــت املــدة ولــم يقــدم اعتراضــه‬\n      ‫فيســقط حقــه يف تدقيــق احلكــم ويصبــح نافــذ ًا ومكتســب ًا للقطعيــة‬\n      ‫ففهــم ذلــك‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/1‬ه ـ‬\n      ‫ويف يــوم األربعــاء املوافــق ‪1434/12/04‬ه ـ افتتحــت اجللســة وقــد‬\n      ‫عــادت املعاملــة مــن االســتئناف بخطابهــم رقــم ‪ 342478012‬يف‬\n      ‫‪1434/11/25‬هـ وبرفقه القرار رقم ‪ 34353899‬يف ‪ 1434/11/09‬ه ـ‬\n      ‫والصــادر مــن الدائــرة اجلزائيــة اخلامســة واملتضمــن املوافقــة علــى احلكم‬\n      ‫وحتــى ال يخفــى جــرى إحلاقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/4‬ه ـ ‪.‬‬\n\n\n\n\n‫‪365‬‬\n\f366\n\f367\n\f368\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":361,"source_page_end":368,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"31b14d16eb3ce15963363ef6e006991fdfaccf89be415c3a47bd4eef0a0a6a8d","normalized_text_hash":"dc3f9ae1dadd5bd143bbb030c4cc967b590c8f5f2c15f3483d3cec205e3bb7fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p361-34286925"},{"id":"39f8bead-8c7d-56f0-b018-c1399133da19","document_type":"judgment","category":"judicial","subcategory":"general","title":"استرداد -مطالبة برد ناقة مفقودة -وصف املدعي للناقة -مصادقة املدعى عليه على وصف املدعي للناقة -اعتبار الوسم داللة امللك -اليمن تشرع يف جانب أقوى املتداعين -حلف املدعي اليمن- إلزام املدعى عليه بتسليم الناقة املوصوفة -إفهام املدعى عليه بأن له الرجوع على من باعه بثمن الناقة .","document_number":"34319310","case_number":"34342741","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/15","year":"1434","subject":"استرداد -مطالبة برد ناقة مفقودة -وصف املدعي للناقة -مصادقة املدعى عليه على وصف املدعي للناقة -اعتبار الوسم داللة امللك -اليمن تشرع يف جانب أقوى املتداعين -حلف املدعي اليمن- إلزام املدعى عليه بتسليم الناقة املوصوفة -إفهام املدعى عليه بأن له الرجوع على من باعه بثمن الناقة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/15 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34319310 :‬‬\n                         ‫َر ْق ُم الدعوى‪34342741 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34329899‬تاريخه‪1434/11/3 :‬هـ‬\n\n\n      ‫اســترداد ‪ -‬مطالبــة بــرد ناقــة مفقــودة‪ -‬وصــف املدعــي للناقة ‪ -‬مصادقة‬\n      ‫املدعــى عليــه علــى وصــف املدعــي للناقــة ‪ -‬اعتبــار الوســم داللــة امللــك‬\n      ‫‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن‪ -‬حلــف املدعــي اليمــن‪-‬‬\n      ‫إلــزام املدعــى عليــه بتســليم الناقــة املوصوفــة‪ -‬إفهــام املدعــى عليــه بــأن‬\n                                         ‫لــه الرجــوع علــى مــن باعــه بثمــن الناقــة ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (إن دماءكــم وأموالكــم وأعراضكــم‬\n                                          ‫عليكــم حــرام) أخرجــه مســلم‪.‬‬\n                 ‫‪ .2‬القاعدة الفقهية‪ :‬األصل بقاء ما كان على ما كان‪.‬‬\n\n\n\n      ‫طالــب املدعــي املدعــى عليــه بــرد ناقتــه املفقــودة ‪ ،‬حيــث فقــد ناقتــه‬\n      ‫وعليهــا وســمه قبــل حوالــي ســنتني وقــد وجدهــا عنــد املدعــى عليــه‪،‬‬\n      ‫أنكــر املدعــى عليــه ودفــع بــأن الناقــة مملوكــة لــه وقــد اشــتراها مــن‬\n      ‫أحــد األشــخاص مببلــغ عشــرة آالف ريــال وليســت ملــك املدعــي‪ ،‬وقــد‬\n      ‫كانــت بينــة املدعــي هــي الوســم الــذي علــى الناقــة وأنــه وســم خــاص‬\n      ‫بإبلــه ال يشــاركه فيــه أحــد ‪ ،‬وقــد صــادق املدعــى عليــه بــأن الوســم‬\n      ‫الــذي علــى الناقــة خــاص باملدعــي ودفــع بشــرائه الناقــة‪ ،‬لكــن أنكــر‬\n\n‫‪369‬‬\n\f‫املدعــي بيــع الناقــة أو التصــرف فيهــا بــأي تصــرف ناقــل مللكيتهــا ‪،‬‬\n‫وعليــه طلــب ناظــر القضيــة مــن املدعــي اليمــن املقويــة لدعــواه ‪ ،‬وحلــف‬\n‫املدعــي بــأن الناقــة ملكــه وأنــه لــم يبعهــا ولــم يهبهــا ألحــد وأنها مــا زالت‬\n‫يف ملكــه ‪ ،‬ومبــا أن املدعــى عليــه صــادق علــى أن الوســم علــى الناقــة‬\n‫خــاص بإبــل املدعــي ‪ ،‬ومبــا أن األصــل بقــاء مــا كان علــى مــا كان‬\n‫ومبــا أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن‪ ،‬ومبــا أن املدعــي‬\n‫تقــوى جانبــه بالوســم وحلــف اليمــن حســب مــا طلــب منــه ‪ ،‬فقــد مت‬\n‫احلكــم بإلــزام املدعــى عليــه بتســليم الناقــة املوصوفــة بالدعــوى للمدعي‬\n‫وإفهامــه بــأن لــه الرجــوع بثمــن الناقــة علــى مــن باعــه ‪ ،‬واعتــرض املدعــى‬\n‫عليــه بــدون الئحــة ‪ ،‬وصــدق احلكــم مــن الدائــرة احلقوقيــة األولــى‬\n                                    ‫مبحكمــة االســتئناف مبنطقــة اجلــوف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة بعرعــر‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بعرعــر برقــم ‪ 34342741‬وتاريــخ ‪ 1434/07/23‬ه ـ املقيــدة باحملكمة‬\n‫برقــم ‪ 341652090‬وتاريــخ ‪ 1434/07/09‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق‪ 1434/09/14‬ه ـ افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا‬\n‫حضــر ‪ ......‬ســعودي بالهويــة رقــم ‪ ......‬مدعيــا علــى احلاضــر معــه ‪......‬‬\n‫ا يف دعــواه عليــه لقــد فقــدت ناقــة مــن‬ ‫ســعودي بالهويــة رقــم ‪ ......‬قائ ـ ً‬\n‫إبلــي وضحــى متيــل إلــى الشــقر عليهــا وســم عبــارة عــن دائــرة يف الفخــذ‬\n‫األميــن مكتــوب بداخلهــا حــرف (‪ )......‬قبــل حوالــي ســنتني ويف جمــادى‬\n‫األولــى مــن هــذا العــام عثــرت عليهــا صدفــة غــرب منطقــة الســليمانية‬\n\n                                                                                          ‫‪370‬‬\n\f      ‫عنــد هــذا احلاضــر فطلبــت منــه تســليمها لــي فرفــض أطلــب إلزامــه‬\n      ‫بتســليمها لــي هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب‬\n      ‫ا بــأن مــا ذكــره املدعــي يف دعــواه مــن أن الناقــة املوصوفــة يف‬         ‫قائ ـ ً‬\n      ‫الدعــوى مملوكــة لــه غيــر صحيــح والصحيــح أنهــا مملوكــة لــي فقــد‬\n      ‫اشــتريتها مــن املدعــو ‪ ......‬مببلــغ وقــدره عشــرة آالف ريــال وال حــق‬\n      ‫للمدعــي يف هــذه الناقــة هكــذا أجــاب وبســؤال املدعــي البينــة علــى‬\n      ‫ا بــأن بينتــي الوســم املوســوم علــى الناقــة وهــو وســم‬   ‫دعــواه أجــاب قائ ـ ً‬\n      ‫خــاص بإبلــي ال يشــاركني فيــه أحــد واملدعــى عليــه ال ينكــر ذلــك‬\n      ‫ال صحيح أن الوســم‬     ‫هكــذا أجــاب وبعرضــه علــى املدعــى عليــه قــرر قائ ً‬\n      ‫املذكــور خــاص بإبــل املدعــى عليــه وهــو موجــود يف الناقــة املوصوفــة‬\n      ‫يف الدعــوى ولكننــي اشــتريت هــذه الناقــة وال حــق لــه فيهــا هكــذا‬\n      ‫قــرر فســألت املدعــي هــل بــاع هــذه الناقــة أو وهبهــا ألحــد مــن قبــل أو‬\n      ‫ا مللكيتهــا فأجــاب قائـاً‪ :‬لــم يســبق لــي بيــع‬  ‫تصــرف فيهــا تصرفــا ناقـ ً‬\n      ‫هــذه الناقــة وال هبتهــا ألحــد مــن قبــل ولــم أتصــرف فيهــا أي تصــرف‬\n      ‫ناقــل مللكيتهــا ومــا زالــت يف ملكــي حتــى اآلن هكــذا أجــاب وبعــرض‬\n      ‫ا واهلل‬‫اليمــن علــى املدعــي املقويــة لدعــواه اســتعد ببذلهــا وحلــف قائ ـ ً‬\n      ‫العظيــم الــذي ال إلــه إال هــو إن الناقــة املوصوفــة يف دعــواي هــي ناقتــي‬\n      ‫ولــم أبعهــا ولــم أهبهــا ألحــد مــن قبــل ومــا زالــت يف ملكــي حتــى اآلن‬\n      ‫واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومبــا أن الطرفــن تصادقــا علــى أن الناقــة املوصوفــة يف الدعــوى بيــد‬\n      ‫املدعــى عليــه وأن الوســم املوســوم علــى الناقــة املذكــورة خــاص بإبــل‬\n      ‫املدعــي ومبــا أن املدعــي قــرر عــدم انتقــال ملكيــة الناقــة لغيــره وقــد‬\n      ‫تقــرر عنــد الفقهــاء بــأن األصــل بقــاء مــا كان علــى مــا كان ومبــا أن‬\n\n\n‫‪371‬‬\n\f‫اليمــن تشــرع يف جانــب أقــوى املتداعيــن ومبــا أن املدعــي تقــوى جانبــه‬\n‫بالوســم املوصــوف يف الدعــوى وحلــف اليمــن الشــرعية حســبما طلــب‬\n‫منــه ولعمــوم قولــه صلــى اهلل عليــه وســلم (إن دماءكــم وأموالكــم‬\n‫وأعراضكــم عليكــم حــرام) أخرجــه مســلم (‪ )1679‬لــذا فقــد قــررت‬\n‫إلــزام املدعــى عليــه بتســليم الناقــة املوصوفــة يف الدعــوى للمدعــي وبــه‬\n‫حكمــت وأفهمــت املدعــى عليــه بــأن لــه الرجــوع بثمــن الناقــة علــى مــن‬\n‫باعــة وبإعــان احلكــم علــى املدعــى عليــه قــرر اعتراضــه عــن احلكــم‬\n‫بــدون الئحــة وســيجري رفــع املعاملــة إلــى محكمــة االســتئناف حســب‬\n‫التعليمــات وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/09/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫األولــى يف محكمــة االســتئناف مبنطقــة اجلــوف علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة يف عرعر برقــم ‪ 34165209‬وتاريخ‬\n‫‪1434/9/17‬ه ـ املقيــدة لــدى هذه احملكمة برقــم ‪ 342232308‬وتاريخ‬\n‫‪1434/9/22‬ه ـ املرفــق بهــا الصــك الصـ ــادر مــن فضيل ـ ــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ......‬برقــم ‪ 34319310‬وتاريــخ ‪1434/9/15‬هـ ـ‬\n‫اخلــاص بدعــوى ‪ ............‬ضــد ‪ ......‬يف قضيــة اســترداد ناقــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة فــإن الدائــرة تقــرر املصادقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                            ‫وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪372‬‬\n\f\f                     ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة املدعي تعويضه من قبل اجلهة املدعى عليها‬\n  ‫‪5‬‬                                                         ‫تعويض‬    ‫‪1‬‬\n                 ‫عن املدة التي قضاها يف السجن‬\n\n\n         ‫مطالبة املدعي للجهة املدعى عليها (ورشة سيارات)‬\n  ‫‪9‬‬                                                         ‫تعويض‬    ‫‪2‬‬\n               ‫بتعويضه عن سيارته التي سرقت منها‬\n\n\n          ‫مطالبة املدعي (شركة سيارات) للمدعى عليه‬\n          ‫بأجرة املثل للفترة ما بني صدور حكم قضائي‬\n  ‫‪20‬‬     ‫سابق بفسخ عقد البيع للسيارة بينهما لوجود العيب‬     ‫تعويض‬    ‫‪3‬‬\n           ‫وحتى قيام املدعى عليه بتسليم السيارة للجهة‬\n                              ‫املدعية‬\n\n\n            ‫مطالبة املدعي للمدعى عليه بتسديد الغرامة‬\n          ‫الشهرية املفروضة بينهما حال تأخر املدعى عليه‬\n  ‫‪25‬‬                                                        ‫تعويض‬    ‫‪4‬‬\n           ‫يف سداد كامل مبلغ العني املشتراة خالل املدة‬\n                               ‫احملددة‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بدفع قيمة إطعام‬\n  ‫‪29‬‬      ‫اإلبل التي سبق وأن اشتراها من شخص (طرف‬            ‫تعويض‬    ‫‪5‬‬\n          ‫ثالث) ثم تبني بعد مدة أنها ملك للمدعى عليه‬\n\n\n         ‫مطالبة املدعي للمدعى عليه باإلقرار باستالم مبلغ‬\n  ‫‪35‬‬                                                   