ولم يسلم املبلغ ملالكها وهو املدعي‬\n\n\n         ‫مطالبة املدعي للمدعى عليه بإعادة البضاعة التي‬\n ‫‪346‬‬                                                       ‫رد مختلَس‬    ‫‪43‬‬\n               ‫اختلسها من املستودع أو تسليم قيمتها‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بإعادة املبالغ التي‬\n ‫‪350‬‬                                                       ‫رد مختلَس‬    ‫‪44‬‬\n                ‫اختلسها منه عندما كان يعمل عنده‬\n\n\n           ‫مطالبة املدعي للمدعى عليه بإعادة املبالغ التي‬\n ‫‪354‬‬                                                       ‫رد مختلَس‬    ‫‪45‬‬\n                ‫اختلسها منه عندما كان يعمل عنده‪.‬‬\n\n\n          ‫مطالبة املدعي للمدعى عليه بإعادة املبالغ التي‬\n           ‫اختلسها منه عندما كان يعمل عنده وحتمل‬\n ‫‪361‬‬                                                       ‫رد مختلَس‬    ‫‪46‬‬\n         ‫اخلسائر الناجتة عن البضائع التي لم يقم بتوزيعها‬\n                          ‫وتلفت بسبب ذلك‬\n\f‫الصفحة‬                   ‫املوضوع‬                    ‫التصنيف‬   ‫م‬\n\n\n         ‫مطالبة املدعي للمدعى عليه باسترداد ناقته‬\n ‫‪369‬‬                                                ‫استرداد‬   ‫‪47‬‬\n           ‫املفقودة والتي وجدها عند املدعى عليه‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":369,"source_page_end":380,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"faaff6e6121fceb8f319e9ed4a6951d0d3ccc57c59fb1834c6534b470b7b19ae","normalized_text_hash":"c5e8bc25d8ee7ce660000b2206a329da2fb8ee9036665f49b0d1d203f6f2dd84","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p369-34319310"},{"id":"32cf2bbe-4b58-5e28-b676-9980335ffaa0","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -وكالة األجنبي لألجنبي -التوكيل أثناء املرافعة - القضاء بالشاهد واليمن -الترجيح بن البينات -رفض شهادة األجير اخلاص -تعديل الشاهد -احلكم بصرف النظر عن الدعوى.","document_number":"34295094","case_number":"3346027","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/28","year":"1434","subject":"قرض -وكالة األجنبي لألجنبي -التوكيل أثناء املرافعة - القضاء بالشاهد واليمن -الترجيح بن البينات -رفض شهادة األجير اخلاص -تعديل الشاهد -احلكم بصرف النظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1433/4/28 :‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                        ‫الص ِّك‪34295094 :‬‬\n                        ‫َر ْق ُم الدعوى‪3346027 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 33308896‬تاريخه‪1434/7/11 :‬هـ‬\n\n\n\n    ‫قــرض ‪ -‬وكالــة األجنبــي لألجنبــي ‪ -‬التوكيــل أثنــاء املرافعــة ‪-‬‬\n    ‫القضــاء بالشــاهد واليمــن ‪ -‬الترجيــح بــن البينــات‪ -‬رفــض شــهادة‬\n    ‫األجيــر اخلــاص‪ -‬تعديــل الشــاهد‪ -‬احلكــم بصــرف النظر عــن الدعوى‪.‬‬\n\n\n\n\n    ‫‪ -1‬القضاء بالشاهد واليمني يف األموال هو مذهب املالكية والشافعية‬\n    ‫واحلنابلــة والظاهريــة وبــه قــال الصحابــة أبوبكــر وعمــر وعثمــان وعلــى‬\n    ‫وغيرهــم ومــن التابعــن عمــر بــن عبدالعزيــز وشــريح واحلســن وفقهــاء‬\n                                                       ‫املدينــة الســبعة وغيرهــم ‪.‬‬\n    ‫‪ -2‬عــن ابــن عبــاس رضــى اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم‬\n    ‫(قضــي بيمــن وشــاهد) أخرجــه مســلم واحمــد وأبــو داود وابــن ماجــه‪.‬‬\n    ‫‪ -3‬عــن جابــر بــن عبــداهلل رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه ســلم‬\n              ‫(قضــى بيمــن وشــاهد) أخرجــه احمــد والترمــذي وابــن ماجــه ‪.‬‬\n    ‫‪ -4‬أخــرج اإلمــام احمــد والدارقطنــى والبيهقــي ومالــك والشــافعي عــن‬\n    ‫جعفــر بــن محمــد عــن أبيــه عــن أميــر املؤمنــن علــى بــن أبــى طالــب‬\n    ‫رضــي اهلل عنــه (أن رســول اهلل صلــى اهلل عليــه وســلم قضــى بشــهادة‬\n    ‫شــاهد واحــد وميــن صاحــب احلــق) وذكــره الترمــذي عــن جعفــر بــن‬\n    ‫محمــد عــن أبيــه عــن أميــر املؤمنــن علــي رضــي اهلل عنــه وأنــه قضــى بــه‬\n                                                                         ‫يف العــراق ‪.‬‬\n\n‫‪5‬‬\n\f‫‪ -5‬أخــرج ابــن ماجــه أن رســول اهلل صلــي اهلل عليــه وســلم أجــاز شــهادة‬\n                                                          ‫الرجــل وميــن الطالــب ‪.‬‬\n‫‪ -6‬قــال املــاوردي ‪ ( :‬ويــدل عليــه انعقــاد اإلجمــاع فقــد قضــى علــي‬\n‫بــن أبــي طالــب بالكوفــة باليمــن مــع الشــاهد علــى املنبــر معنــاه ‪ :‬أنــه‬\n‫احلــف املدعــى قائمــا علــى املنبــر وروى أبــو الزنــاد عــن عبــداهلل بــن عامــر‬\n‫قــال شــهدت رســول اهلل صلــى اهلل عليــه وســلم وأبــا بكــر وعمــر يقضــون‬\n‫باليمــن مــع الشــاهد وأخبــر يحيــى أنــه قــال بــه ‪ :‬كعــب وزيــد بــن‬\n‫ثابــت وقضــى بهــا عمــر بــن عبدالعزيــز وكتــب إلــى خلفائــه يف جميــع‬\n‫األمصــار ومثــل هــذا العمــل املشــهور إذا لــم يعــارض باخلــاف كان‬\n                                                     ‫إجماع ـ ًا وحجاب ـ ًا قاطع ـ ًا) ‪.‬‬\n‫‪ -7‬جــاء يف كشــاف القنــاع (‪ ( : )324/15‬ويقبــل يف مــال ومــا يقصــد بــه‬\n‫املــال كالبيــع وأجلــه ‪ ..‬رجــان أو رجــل وامرأتــان أو رجــل وميــن املدعــي‬\n‫ملــا روى ابــن عبــاس أن رســول اهلل صلــى اهلل عليــه وســلم قضــى باليمــن‬\n‫مــع الشــاهد ‪ ..‬وألن املدعــي هنــا قــوي جانبــه بالشــاهد وظهــر صدقــه‬\n                                    ‫أشــبه صاحــب اليــد واملنكــر لقــوة جانبــه)‪.‬‬\n‫‪ -8‬جــاء يف الشــرح املمتــع البــن عثيمــن (‪ ( : )450/15‬قولــه ‪ :‬رجــان أو‬\n‫رجــل وامرأتــان أو رجــل وميــن املدعــي ‪ .‬ثالثــة أنــواع مــن البينــات رجالن‬\n‫أو رجــل وامرأتــان أو رجــل وميــن املدعــي ‪ ،‬أمــا رجــل وميــن املدعــي ‪..‬‬\n‫فحديــث ابــن عبــاس الــذي أخرجــه مســلم ‪ ،‬وحكــم الرســول صلــى اهلل‬\n                   ‫عليــه وســلم دليــل ألنــه مشــرع عليــه الصــاة والســام) ‪.‬‬\n\n\n\n\n                                                                                          ‫‪6‬‬\n\f    ‫ادعــى وكيــل املدعــي علــى املدعــى عليــه وكالــة بــأن موكلــه أقــرض‬\n    ‫املدعــى عليــه أصالــة ثالثمائــة وخمســة وتســعني ألــف ريــال مبوجــب‬\n    ‫شــيك مصــريف ‪ ،‬طلــب إلــزام املدعــى عليــه بســداد هــذا املبلــغ ‪ ،‬أجــاب‬\n    ‫املدعــى عليــه وكالــة بصحــة اســتالم موكلــه للشــيك املذكــور ‪ ،‬دفــع‬\n    ‫املدعــى عليــه وكالــة بــأن هــذا الشــيك ســداد لقــرض ســابق أقرضــه‬\n    ‫موكلــه للمدعــي أصالــة ‪ ،‬أنكــر املدعــي وكالــة هــذا الدفــع ‪ ،‬أحضــر‬\n    ‫املدعــى عليــه شــاهدا علــى صحــة الدفــع ‪ ،‬جــرى تدويــن الشــهادة ‪،‬‬\n    ‫بعــرض الشــاهد وشــهادته علــى املدعــي وكالــة قــال الشــاهد ال أعرفــه‬\n    ‫وشــهادته غيــر صحيحــة ‪ ،‬جــرى تعديــل الشــاهد ‪ ،‬قــرر املدعــي وكالــة‬\n    ‫أن لديــه شــهود ًا علــى صحــة دعــواه ‪ ،‬أحضــر شــهوده وشــهدوا مبــا لديهــم‬\n    ‫‪ ،‬لــم يظهــر للمحكمــة أن الشــهادة موصلــة ‪ ،‬طلــب مــن املدعــى عليــه‬\n    ‫أصالــة اليمــن تكملــة لبينتــه ‪ ،‬حلــف املدعــى عليــه أصالــة اليمــن ‪،‬‬\n    ‫صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي وإخــاء ســبيل املدعــى‬\n    ‫عليــه مــن هــذه الدعــوى ‪ ،‬اعتــرض املدعــي وكالــة ‪ ،‬لوحــظ علــى احلكــم‬\n    ‫مــن محكمــة االســتئناف ‪ ،‬حضــر املدعــي أصالــة وقــرر أن أســاس املبلــغ‬\n    ‫املدعــى بــه ليــس قرضــة وإمنــا مــن أجــل أن يقــوم املدعــى عليــه أصالــة‬\n    ‫بجلــب بضاعــة مــن اخلــارج وللمدعــي أصالــة ‪ %60‬مــن األربــاح ‪ ،‬جــرى‬\n    ‫ســؤال املدعــي اصالــة البينــة علــى مــا ذكــره مؤخــر ًا ‪ ،‬قــرر أنــه ال بينــة‬\n    ‫لديــه وأن االتفــاق كان شــفهيا وليــس لديــه ســوى الشــيك املذكــور ‪،‬‬\n    ‫مبــا أن املدعــي ال بينــة لديــه علــى أن التعامــل عبــارة عــن اتفــاق شــراكة‬\n    ‫ومبــا أن املدعــى عليــه حلــف اليمــن ســابقا لــم يظهــر للقاضــي خــاف مــا‬\n\n‫‪7‬‬\n\f                ‫حكــم بــه ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3346027‬وتاريــخ ‪1433/01/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33118373‬وتاريــخ ‪1433/01/17‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق ‪1433/03/21‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪06‬‬\n‫‪ 09 :‬وفيهــا حضــر ‪ ...‬ميانــي اجلنســية رقــم اإلقامــة ‪ ...‬الصــادرة مــن‬\n‫رأس تنــورة بالوكالــة عــن ‪ ...‬ميانــي اجلنســية رقــم اإلقامــة ‪ ...‬مبوجــب‬\n‫الوكالــة رقــم ‪ 1938‬يف ‪1433/1/3‬ه ـ الصــادرة مــن كتابــة عــدل وزارة‬\n‫الداخليــة وفيهــا حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وحضــور‬\n‫اجللســات وإقامــة الدعــاوى والــرد واإلقــرار واإلنــكار والصلــح وقبــول‬\n‫األحــكام وردهــا ونفيهــا وطلــب االســتئناف وادعــى علــى احلاضــر معــه‬\n‫‪ ...‬ســعودي اجلنســية رقــم الســجل املدنــي ‪ ...‬بصفتــه وكيــا عــن ‪...‬‬\n‫ســعودي اجلنســية رقــم الســجل املدنــي ‪ ...‬مبوجــب الوكالــة رقــم ‪11634‬‬\n‫يف ‪1333/2/13‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة يف الريــاض‬\n‫وفيهــا حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى‬\n‫وســماعها والــرد عليهــا واإلقــرار واإلنــكار والصلــح وطلــب وقبــول‬\n‫احلكــم ونفيــه واالعتــراض عليــه وطلــب التمييــز قائــا يف حتريــر دعــواه‬\n‫إن املدعــي أخــي وهــو ســجني يف مبالــغ ماليــة واالختــاف يف االســم عائد‬\n‫عنــد إصــدار اإلقامــة وقــد أقــرض موكلــي املدعــى عليــه أصالــة مبلغــا‬\n\n\n                                                                                   ‫‪8‬‬\n\f    ‫قــدره ثالثمائــة وخمســة وتســعون ألــف ريــال قرضة حســنة مبوجب شــيك‬\n    ‫مصــريف مســحوب علــى البنــك األهلــي أطلــب إلــزام املدعــى عليــه بســداد‬\n    ‫هــذا املبلــغ ملوكلــي علمــا أنــه اآلن يف الســجن مســجون يف مبلــغ قــدره‬\n    ‫مليونــا ريــال تقريبــا هــذه دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي‬\n    ‫علــى املدعــى عليــه وكالــة قــال مــا ذكــره املدعــي وكالــة مــن اســتالم‬\n    ‫موكلــي للشــيك فصحيــح ولكــن هــذا املبلــغ كان موكلــي قــد‬\n    ‫أقرضــه للمدعــي وهــذا الشــيك ســداد للقــرض هكــذا ذكــر وبعــرض‬\n    ‫ذلــك علــى املدعــي وكالــة قــال الصحيــح مــا جــاء يف دعــواي وموكلــي‬\n    ‫لــم يقتــرض مــن املدعــى عليــه أي مبلــغ هكــذا ذكــر وبعــد ذلــك جــرى‬\n    ‫ســؤال املدعــى عليــه ألديــك بينــة علــى دعــواك فأجــاب قائــا لــدي بينــة‬\n    ‫وهــي شــاهد حاضــر اآلن أطلــب ســماع شــهادته هكــذا أجــاب وأحضــر‬\n    ‫للشــهادة ‪ ...‬اجلنســية رقــم الســجل املدنــي ‪ ...‬صــادر الدمــام وبســؤاله عمــا‬\n    ‫لديــه مــن شــهادة قــال أشــهد بأنــه قبــل ســنتني تقريبــا كنــت أنــا واملدعــى‬\n    ‫عليــه واملدعــي يف بيــت املدعــى عليــه حيــث أن املدعــي يطلــب مــن املدعى‬\n    ‫عليــه مبلغــا قــدره اربعمائــة وخمســة آالف ريــال ســلفة فقــام بتســليمه‬\n    ‫مبلــغ قــدره مائتــان وخمســون آلــف ريــال بعــد أســبوع ثــم يف األســبوع‬\n    ‫الثانــي تقريبــا ســلمه مائــة وخمســة وخمســن آلــف ريــال وســلم املدعــي‬\n    ‫للمدعــى عليــه شــيك مببلــغ قــدره أربعمائــة وخمســة أالف ريــال ضمانــا‬\n    ‫حلقــه وقــد قــام املدعــي بتســليم املدعــى عليــه شــيك مصــريف مســحوب‬\n    ‫علــى البنــك ‪ ...‬ســداد للقــرض وكان مبلــغ الشــيك قــدره ثالثمائــة‬\n    ‫وخمســة وتســعون ألــف ريــال بتاريــخ ‪2010 /7/7‬م تقريبــا هكــذا شــهد‬\n    ‫وبعــرض الشــاهد ومــا جــاء يف شــهادته علــى املدعي وكالة قال الشــاهد‬\n    ‫ال أعرفــه ومــا جــاء يف شــهادته فغيــر صحيــح وبعــد ذلــك جــرى ســؤال‬\n\n\n‫‪9‬‬\n\f‫املدعــى عليــه وكالــة عــن الشــيك املســلم ملوكلــه مــن املدعــي وهــل لديــه‬\n‫زيــادة بينــة فأجــاب قائــا‪ :‬الشــيك موكلــي لــم يعثــر عليــه ورقــم الشــيك‬\n‫واحــد وســتون مســحوب مــن مصــرف ‪ ...‬بتاريــخ ‪1430/4/22‬ه ـ وميكــن‬\n‫طلبــه مــن املدعــي وليــس لــدى موكلــي ســوى الشــاهد احلاضــر هكــذا‬\n‫أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال ســأراجع موكلــي ودفتــر‬\n‫الشــيكات اخلــاص بــه هكــذا ذكــر بعــد ذلــك والنتهــاء وقــت اجللســة‬\n‫جــرى رفعهــا وأفهمــت املدعــى عليــه وكالــة بإحضــار مزكيني للشــاهد‬\n‫وحضــور موكلــه يف اجللســة القادمــة وحــدد املوعــد القــادم يــوم الثالثــاء‬\n‫املوافق ‪1433/4/6‬هـ الســاعة احلادية عشــر والنصف ويف يوم الثالثاء‬\n‫املوافــق ‪ 1433/04/06‬ه ـ حضــر املدعــي وكالــة واملدعــى عليه وكالة‬\n‫كمــا حضــر املدعــى عليــه أصالــة ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ...‬وبعــرض مــا مت ضبطــه ســابق ًا علــى املدعــى عليــه أصالــة‬\n‫قــال مــا ذكــره موكلــي كلــه صحيــح بعــد ذلــك قــال املدعــى عليــه‬\n‫وكالــة املزكــن موجوديــن اآلن و أطلــب ســماع شــهادتهما وأحضــر‬\n‫للشــهادة ‪ ...‬مينــي اجلنســية مبوجــب اإلقامــة رقــم ‪ ...‬صــادر الريــاض و ‪...‬‬\n‫مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪ ...‬صــادر الريــاض وبســؤالهما‬\n‫عــن عمرهمــا و عملهمــا و مقــر ســكنهما و قرابتهمــا للطرفــن و‬\n‫الشــاهد و مــا لديهمــا مــن شــهادة فقــال األول عمــري ‪ 34‬ســنة و أعمــل‬\n‫يف شــركة ‪ ...‬للشــحن وصاحــب املؤسســة هــو املدعــى عليــه أصالــة و‬\n‫قــال الثانــي عمــري ‪ 40‬ســنة وأعمــل يف شــركة ‪ ...‬للشــحن وصاحــب‬\n‫املؤسســة هــو املدعــى عليــه وقــاال جميعـ ًا نحــن نعمــل لــدى الشــركة وال‬\n‫عمــل لنــا آخــر غيــر ذلــك هكــذا ذكــرا و نظــر ًا لعملهمــا يف شــركة‬\n‫املدعــى عليــه أفهمــت املدعــى عليــه بإحضــار مزكيــن آخريــن بعــد‬\n\n\n                                                                                    ‫‪10‬‬\n\f     ‫ذلــك جــرى ســؤال املدعــى وكالــة عــن دفتــر الشــيكات فقــال لقــد‬\n     ‫راجعــت موكلــي و أفــاد مبــا ذكرتــه يف الدعــوى ودفتــر الشــيكات‬\n     ‫موجــود يف منــزل املدعــي ولــم أطلــع عليــه هكــذا ذكــر والنتهــاء وقــت‬\n     ‫اجللســة جــرى رفعهــا وحــدد املوعــد القــادم يــوم ‪1433/04/27‬ه ـ الثالثاء‬\n     ‫الســاعة العاشــرة ويف يــوم الثالثــاء املوافــق ‪ 1433/04/27‬ه ـ حضــر‬\n     ‫املدعــي وكالــة‪ ...‬واملدعــى عليــه أصالــة ووكيلــه وبســؤال املدعــى عليــه‬\n     ‫عــن املزكيــن أحضــر للشــهادة ‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم‬\n     ‫‪ ...‬و‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...‬وبســؤالهما عــن عمرهمــا‬\n     ‫ومقــر ســكنهما وعملهمــا وعالقتهمــا للطرفــن والشــاهد ومــا لديهمــا‬\n     ‫مــن شــهادة أجــاب األول قائــا عمــري ‪ 22‬ســنة وأعمــل لــدى شــركة‬\n     ‫‪ ...‬للذهــب واملجوهــرات وأســكن يف حــي ‪ ...‬واملدعــى عليــه والشــاهد‬\n     ‫مــن القرابــة البعيــدة وال قرابــة مــع املدعــي وأجــاب الثانــي قائــا عمــري‬\n     ‫‪ 23‬ســنة وأعمــل يف ســوبر ماركــت ‪ .......‬وأســكن يف حــي ‪ ...‬واملدعــى‬\n     ‫عليــه والشــاهد مــن القبيلــة وال قرابــة لــي مــع املدعــي وشــهد كل واحــد‬\n     ‫منهمــا مبفــرده قائــا أشــهد مبــا أن الشــاهد ‪ ...‬عــدل ثقــة هكــذا شــهدا‬\n     ‫بعــد ذلــك جــرى ســؤال املدعــى عليــه عــن املبلــغ املتبقــي وهــو عشــرة آالف‬\n     ‫ريــال فقــال مت حتويلهــا عــن طريــق البنــك وســأحضر مــا يثبــت التحويــل‬\n     ‫يف اجللســة القــادة بعــد ذلــك جــرى ســؤال املدعــى عليــه عــن تاريــخ شــيك‬\n     ‫الضمــان ورقمــه فقــال الشــيك مســحوب علــى مصــرف ‪ ...‬برقــم ‪ 15‬فيمــا‬\n     ‫أظــن وتاريــخ ‪ 1430/4/22‬ه ـ هكــذا ذكــر بعــد ذلــك أفهمــت املدعــي‬\n     ‫وكالــة بإحضــار كعــب الشــيكات الصــادرة مــن موكلــه مــن مصــرف‬\n     ‫‪ ...‬بالتاريــخ املذكــور لــذا جــرى رفــع اجللســة وحــدد املوعــد القــادم يــوم‬\n     ‫الســبت املوافــق ‪ 1433/5/22‬ه ـ الســاعة احلاديــة عشــر والنصــف ويف‬\n\n\n‫‪11‬‬\n\f‫يــوم الســبت املوافــق‪ 1433/05/22‬ه ـ حضــر املدعــي وكالــة ولــم‬\n‫يحضــر املدعــى عليــه وبســؤال املدعــي وكالــة عــن دفتــر الشــيكات‬\n‫فأجــاب قائــا الدفتــر وجدتــه ولكــن الكعــوب لــم يكتــب فيهــا شــيء‬\n‫ومســتعد بإحضــار الدفتــر يف اجللســة القادمــة هكــذا ذكــر وأثنــاء ذلك‬\n‫حضــر املدعــى عليــه وبســؤاله عــن ســبب االختالف يف رقم الشــيك الذي‬\n‫ذكــره حيــث ذكــر يف اجللســة األولــى رقمــا يختلف عــن الرقم املذكور‬\n‫يف اجللســة الســابقة وإثبــات التحويــل فأجــاب قائــا الشــيك رقمــه ‪15‬‬\n‫وأنــا لــم احضــر اجللســة األولــى وإمنــا وكيلــي وأمــا إثبــات التحويــل فــإن‬\n‫املدعــي مقــر بذلــك فيمــا أعلــم ومرفــق صــورة مــن احلــواالت هكــذا‬\n‫ذكــر وبعــرض ذلــك علــى املدعــي وكالــة قــال صحيــح أن موكلــي‬\n‫حــول مبلــغ قــدره عشــرة آالف للمدعــى عليــه بنــاء علــى طلــب منــه وهــي‬\n‫تابعــة للقــرض هكــذا ذكــر والنتهــاء وقــت اجللســة جــرى رفعهــا وحــدد‬\n‫املوعــد القــادم يــوم الثالثــاء ‪1433/06/17‬ه ـ الســاعة التاســعة ويف يــوم‬\n‫الثالثاء املوافق ‪ 1433/06/17‬هـ افتتحت اجللســة اخلامســة الســاعة ‪00‬‬\n‫‪ 09 :‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة كمــا حضــر‬\n‫‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم ‪ ...‬وقــرر املدعــي وكالــة املخــول‬\n‫لــه يف وكالتــه حــق توكيــل الغيــر بــأن احلاضــر ‪ ....‬وكيــل عنــه بصفتــه‬\n‫وكيــا عــن املدعــي يف كل مــا هــو مخــول بــه يف الوكالــة وبســؤال‬\n‫املدعــي وكالــة عــن دفتــر الشــيكات أجــاب قائــا الدفتــر أحضرتــه‬\n‫ولــم أجــد غيــر دفتــر واحــد هكــذا أجــاب وأبــرز دفتــر شــيكات علــى‬\n‫مطبوعــات مصــرف ‪ .....‬يبــدأ برقــم ‪ 26‬وينتهــي برقــم ‪ 75‬ولــم يــدون‬\n‫علــى كعــوب الشــيكات أي كالم بعــد ذلــك جــرى ســؤال الطرفــن‬\n‫ألديكمــا زيــادة أقــوال أو بينــات فقــاال جميعــا ليــس لدينــا مــا نذكــره‬\n\n\n                                                                                      ‫‪12‬‬\n\f     ‫هكــذا ذكــرا ولــذا جــرى رفــع اجللســة وأفهمــت املدعــى عليــه وكالــة‬\n     ‫بحضــور موكلــه يف اجللســة القادمــة ألداء اليمــن وحــدد املوعــد القــادم‬\n                      ‫يــوم اإلثنــن ‪1433/7/7‬ه ـ الســاعة احلاديــة عشــر والنصــف‬\n     ‫ويف يــوم اإلثنــن املوافــق ‪ 1433/07/07‬ه ـ افتتحــت اجللســة السادســة‬\n     ‫الســاعة ‪ 11 : 30‬وفيهــا حضــر املدعــي وكالــة ‪ ...‬واملدعــي وكالــة ‪...‬‬\n     ‫واملدعــى عليــه أصالــة ‪ ...‬ووكيلــه ‪ ...‬وقــال املدعــى عليــه أصالــة اتضــح‬\n     ‫لــي أن الشــيك رقمــه ‪ 61‬هكــذا ذكــر بعــد ذلــك قــال املدعــي وكالــة‬\n     ‫‪ ...‬هنــاك شــهود علــى أن املبلــغ قــرض وليــس ســداد للديــن وهــم ‪ ...‬و‪...‬‬\n     ‫و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ومســتعد بإحضارهــم يف اجللســة القادمــة هكــذا ذكــر‬\n     ‫لــذا قــررت رفــع اجللســة دون أخــذ ميــن املدعــى عليــه حتــى ســماع الشــهود‬\n     ‫وحــدد املوعــد القــادم يــوم اإلثنــن ‪1433/7/21‬ه ـ الســاعة الثانيــة عشــر‬\n     ‫والنصــف ويف يــوم اإلثنــن املوافق‪1433/07/21‬ه ـ حضــر املدعــي‬\n     ‫وكالــة ‪ ....‬واملدعــي وكالــة ‪ ...‬واملدعــى عليــه أصالــة ‪ ...‬ووكيلــه ‪...‬‬\n     ‫وبســؤال املدعــي وكالــة عــن شــهوده فأجــاب قائــا لدي شــاهدين أطلب‬\n     ‫ســماع شــهادتهما هكــذا أجــاب وأحضــر للشــهادة ‪ ......‬مينــي اجلنســية‬\n     ‫مبوجب إقامة رقم ‪ ...‬و‪ ...‬ميني اجلنســية مبوجب إقامة رقم ‪ ...‬وبســؤالهما‬\n     ‫عمــا لديهمــا مــن شــهادة شــهد األول قائــا إنــه قبــل ســتة أشــهر تقريبــا‬\n     ‫اجتمعنــا أنــا و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬وغيرهــم يف منــزل ‪ ...‬الواقــع يف ‪ ...‬بعــد‬\n     ‫صــاة املغــرب وحصــل نقــاش بــن ‪ ...‬و‪ ...‬وقــال ‪ ...‬إنــي اســتلمت مــن ‪...‬‬\n     ‫مبلغــا وقــدره مائــة وخمســون ألــف ريــال وال أعلــم مــا أســاس املبلــغ أو ملــن‬\n     ‫هكــذا شــهد وشــهد الثانــي قائــا إنــه قبــل أربعــة أشــهر تقريبــا اجتمعنــا‬\n     ‫أنــا و‪ ...‬ومعــه شــخص آخــر و‪ ...‬و ‪ ...‬و‪ ...‬وغيرهــم يف منــزل ‪ ...‬الواقــع يف‬\n     ‫حــي ‪ .....‬بعــد صــاة املغــرب وحصــل نقــاش حــول املبالــغ املختلــف فيهــا‬\n\n\n‫‪13‬‬\n\f‫بــن ‪ ...‬و‪ ...‬ومت االتفــاق علــى االجتمــاع لــدى ‪ ...‬ومت االجتمــاع عنــده بعــد‬\n‫أســبوع وحصــل نقــاش حــول املبالــغ وقــد أقــر ‪ ...‬باســتالم مبالــغ مــن ‪...‬‬\n‫دون حتديــد مبالــغ معينــة وأنــه يوجــد حســابات بينهــم وطلــب املســتضيف‬\n‫اختيــار ضمــن مــن كال الطرفــن فخرجنــا وال أعلم مــا حصل بعد ذلك‬\n‫هكــذا شــهد بعــد ذلــك قــال املدعــي وكالــة لــدي شــاهد ثالــث وأحضــر‬\n‫للشــهادة ‪ ...‬مينــي اجلنســية مبوجــب إقامــة رقــم ‪ ...‬وبســؤاله عمــا لديــه مــن‬\n‫شــهادة قــال أشــهد بأنــه قبــل ســتة أشــهر تقريبــا اجتمعــت أنــا و‪ ...‬ومعــه‬\n‫شــخص آخــر و‪ ...‬و ‪ ...‬و‪ ...‬و‪ ...‬يف منــزل ‪ ...‬مــن أجــل إنهــاء النــزاع احلاصــل‬\n‫بــن عمــي املدعــي واملدعــى عليــه ‪ ...‬وقــد أقــر املدعــى عليــه باســتالم‬\n‫مبالــغ منهــا ‪150‬ألــف ريــال ســلمتها لــه أنــا نقــدا ومبلــغ ‪ 395‬ألــف ريــال‬\n‫مبوجــب شــيك ومائــة ألــف ريــال ولكنــه ذكــر وجــود حســابات بينهمــا‬\n‫وأنــا ال أعلــم مــا أســاس هــذه املبالــغ وهــل هــي جتــارة أو قــرض وطلــب‬\n‫املســتضيف اختيــار ضمينــن ونظــرا لعــدم اســتعدادنا إلحضــار ضمــن‬\n‫رفضنــا ذلــك هــذا مــا لــدي مــن شــهادة وبــه أشــهد هكــذا شــهد وبعــد‬\n‫ذلــك جــرى ســؤال املدعــي وكالــة‪ ...‬هــل الشــهود اآلخريــن سيشــهدون‬\n‫مبثــل شــهادة مــن حضــر فأجــاب قائــا نعــم هكــذا أجــاب وبعــرض‬\n‫الشــهود ومــا جــاء يف شــهادتهم علــى املدعــى عليــه فقــال الشــهود ال‬\n‫أعرفهــم ومــا جــاء يف شــهادتهم مــن ذكــر ملبالــغ محــددة غيــر صحيــح‬\n‫بــل أنــا ذكــرت أن بيننــا حســابات فقــط هكــذا أجــاب والنتهــاء وقــت‬\n‫اجللســة جــرى رفعهــا وحــدد املوعــد القــادم يــوم الثالثــاء ‪1433/7/29‬ه ـ‬\n‫الســاعة ‪ 1‬ظهــرا ويف يــوم الثالثــاء املوافــق‪ 1433/07/29‬ه ـ حضــر‬\n‫املدعيــان بالوكالــة ‪ ...‬و‪ ...‬وحضــر حلضورهمــا املدعــى عليــه أصالــة‬\n‫وقــال املدعــي وكالــة ‪ ...‬الشــاهد ‪ ...‬حاضــر ولديــه أقــوال أطلــب ســماع‬\n\n\n                                                                                       ‫‪14‬‬\n\f     ‫شــهادته هكــذا ذكــر وحضــر الشــاهد وبســؤاله عمــا لديــه فأجــاب‬\n     ‫قائــا إن املدعــي وكالــة ذكــر يف االجتمــاع مبالــغ منهــا مائــة ألــف‬\n     ‫ومائــة وخمســن ألــف وشــيك مببلــغ وقــدره ثالثمائــة وخمســة وتســعون‬\n     ‫ألــف ريــال وصــادق املدعــى عليــه علــى اســتالمه لهــذه املبالــغ ولكنــه‬\n     ‫ذكــر وجــود حســابات بينهمــا وهــذا مــا لــدي هكــذا أجــاب بعــد ذلــك‬\n     ‫طلبــت مــن املدعــى عليــه اليمــن واســتعد بأدائهــا فأذنــت لــه فحلف قائال‬\n     ‫(واهلل بــأن املبلــغ املدعــى بــه البالــغ قــدره ثالثمائــة وخمســة وتســعون ألفــا‬\n     ‫املســلم لــي مــن املدعــي مبوجــب شــيك مصــريف مســحوب علــى مصــرف‬\n                      ‫األهلــي هــو ســداد لدينــي الثابــت بذمتــه ) هكــذا حلــف‬\n     ‫ـاء علــى مــا تقــدم وملــا جــاء يف شــهادة الشــاهد املعــدل حســب األصول‬    ‫فبنـ ً‬\n     ‫الشــرعية ومبــا أن املدعــى عليــه أدى اليمــن بالصفــة املذكــورة بعاليــه‬\n     ‫ومبــا أن القضــاء بالشــاهد واليمــن جائــز شــرع ًا يف األمــوال وهــو‬\n     ‫مذهــب املالكيــة والشــافعية واحلنابلــة والظاهريــة وقــال بــه الصحابــة‬\n     ‫رضــوان اهلل عليهــم أبــو بكــر وعمــر وعثمــان وعلــي وزيــد وجابــر وأبــو‬\n     ‫هريــرة وابــن عبــاس و مــن التابعــن عمــر بــن عبــد العزيــز وشــريح‬\n     ‫واحلســن وفقهــاء املدينــة الســبعة وعبــد اهلل بــن عتبــة وأبــو ســلمه ابــن‬\n     ‫عبــد الرحمــن وإيــاس وغيرهــم وجــاء عــن ابــن عبــاس رضــي اهلل عنهمــا‬\n     ‫يف احلديــث الــذي أخرجــه مســلم وأحمــد وأبــو داود وابــن ماجــه أن‬\n     ‫النبــي صلــى اهلل عليــه وســلم (قضــى بيمــن وشــاهد) وهــذا احلديــث‬\n     ‫نــص يف جــواز القضــاء بالشــاهد واليمــن فلــو كان القضــاء بالشــاهد‬\n     ‫مــع اليمــن غيــر جائــز ملــا جــاز للنبــي صلــى اهلل وعليــه وســلم أن يقضــي‬\n     ‫بــه ثــم يســكت دون بيــان لعــدم جــواز القضــاء بذلــك كمــا أخــرج أحمــد‬\n     ‫و الترمــذي وابــن ماجــه مــن حديــث جابــر بــن عبــد اهلل رضــي اهلل عنــه‬\n\n\n‫‪15‬‬\n\f‫أن النبــي صلــى اهلل عليــه وســلم قضــى باليمــن مــع الشــاهد كمــا‬\n‫أخــرج أحمــد والــدار قطنــي والبيهقــي ومالــك والشــافعي عــن جعفــر ابــن‬\n‫محمــد عــن أبيــه عــن أميــر املؤمنــن علــي رضــي اهلل عنــه (أن رســول اهلل‬\n‫صلــى اهلل عليــه وســلم قضــى بشــهادة شــاهد واحــد وميــن صاحــب احلــق)‬\n‫وذكــره الترمــذي عــن جعفــر ابــن محمــد عــن أبيــه عــن أميــر املؤمنــن‬\n‫علــي رضــي اهلل عنــه وأنــه قضــى بــه يف العــراق كمــا أخــرج ابــن ماجــه‬\n‫عــن سـ ّـرق أن رســول اهلل صلــى اهلل عليــه وســلم أجــاز شــهادة الرجــل‬\n‫وميــن الطالــب كمــا أن القضــاء بالشــاهد واليمــن مجمــع عليــه فقــد‬\n‫قضــى بــه اخللفــاء األربعــة وعــدد كثيــر مــن الصحابــة ولــم يخالفهــم‬\n‫يف ذلــك أحــد فيكــون إجماع ـ ًا وهــو إجمــاع ســكوتي قــال املــاوردي‬\n‫(ويــدل عليــه انعقــاد اإلجمــاع فقــد قضــى علــي بــن أبــي طالــب بالكوفــة‬\n‫باليمــن مــع الشــاهد علــى املنبــر معنــاه أنــه أحلــف املدعــي قائم ـ ًا علــى‬\n‫املنبــر و روى أبــو الزنــاد عــن عبــداهلل بــن عامــر قــال شــهدت رســول اهلل‬\n‫صلــى اهلل عليــه وســلم وأبــا بكــر وعمــر يقضــون باليمــن مــع الشــاهد‬\n‫وأخبــر يحيــى أنــه قــال بهــا كعــب وزيــد بــن ثابــت وقضــى بهــا عمــر‬\n‫بــن عبــد العزيــز وكتــب إلــى خلفائــه يف جميــع األمصــار ومثــل هــذا‬\n‫العمــل املشــهور إذا لــم يعــارض باخلــاف كان إجماعـ ًا وحجابـ ًا قاطعـاً)‬\n‫وجــاء يف كشــاف القنــاع ‪( 324/15‬ويقبــل يف مــال ومــا يقصــد بــه املــال‬\n‫كالبيــع وأجلــه ‪..‬رجــان أو رجــل وامرأتــان أو رجــل وميــن املدعــي ملــا‬\n‫روى ابــن عبــاس أن رســول اهلل صلــى اهلل عليــه وســلم قضــى باليمــن مــع‬\n‫الشــاهد ‪..‬وألن املدعــي هنــا قــوي جانبــه بالشــاهد وظهــر صدقــه أشــبه‬\n‫صاحــب اليــد واملنكــر لقــوة جانبــه) وجــاء يف الشــرح املمتــع للشــيخ‬\n‫محمــد بــن صالــح العثيمــن ‪ (450/15‬قولــه رجــان أو رجــل وامرأتــان‬\n\n\n                                                                                      ‫‪16‬‬\n\f     ‫أو رجــل وميــن املدعــي ثالثــة أنــواع مــن البينــات رجــان أو رجــل وامرأتــان‬\n     ‫أو رجــل وميــن املدعــي أمــا رجــل وميــن املدعــي فلحديــث ابــن عبــاس‬\n     ‫الــذي أخرجــه مســلم وحكــم الرســول صلــى اهلل عليــه وســلم حكــم‬\n     ‫ودليــل ألنــه مشــرع عليــه الصــاة والســام) ومبــا أن ممــا يؤيــد صحــة‬\n     ‫مــا ذكــره املدعــى عليــه هــو حوالــة مبلــغ قــدره عشــرة آالف ريــال مــن‬\n     ‫املدعــي للمدعــى عليــه ولــم يذكرهــا املدعــي وكالــة يف طلبــه رغــم‬\n     ‫إقــرار ه بكونهــا مــن القــرض ومبــا أن بينــة املدعــى عليــه موصلــة وال‬\n     ‫عبــرة ببينــة املدعــي علــى فــرض ثبوتهــا ألن املدعــى عليــه يدعــي أمــرا‬\n     ‫ناقــا للحــق ولــم ينــف اســتالمه للمبلــغ املدعــى بــه مــن املدعــي وشــهود‬\n     ‫املدعــي وكالــة لــم يثبتــوا أمــرا جديــدا بــل ولــم يعلمــوا ما أســاس التعامل‬\n     ‫بــن املدعــي واملدعــى عليــه ومت ســماع مــا ذكــره املدعــي وكالــة مــن‬\n     ‫بينــة الحتمــال وجــود وقائــع مؤثــرة وخصوصــا مــع وجــود شــاهد واحــد‬\n     ‫للمدعــى عيلــه فقــط وجلميــع مــا تقــدم فقــد أخليــت ســبيل املدعــى عليــه‬\n     ‫مــن هــذه الدعــوى وبعــرض احلكــم علــى املدعيــن بالوكالــة قــررا عــدم‬\n     ‫قناعتهمــا بــه وطالبــا بتدقيــق احلكــم واســتعدا بتقــدمي الئحــة اعتراضيــة‬\n     ‫وأفهمــا بأنــه لهمــا مــدة قدرهــا ثالثــون يــوم لتقــدمي اعتراضهمــا اعتبــارا‬\n     ‫مــن تاريــخ اســتالم صــورة مــن نســخة احلكــم وإذا مضــت املــدة احملــددة‬\n     ‫لالعتــراض ولــم يقدمــا الئحتهمــا فيهــا ســقط حقهمــا يف االســتئناف‬\n     ‫واكتســب احلكــم القطعيــة وحــدد موعــد تســليم صــورة نســخة احلكــم‬\n     ‫هــذا اليــوم الســاعة الثانيــة ظهــرا ومت إقفــال اجللســة الســاعة الواحــدة‬\n     ‫والنصــف ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/29‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n\n\n‫‪17‬‬\n\f‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 3346027‬وتاريــخ ‪1433/01/17‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33118373‬وتاريــخ ‪1433/01/17‬ه ـ ففــي‬\n‫يــوم االثنــن املوافــق ‪1433/11/15‬ه ـ حيــث عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف مبوجــب خطــاب رئيــس محكمــة االســتئناف رقــم‬\n‫‪ 331753042‬يف ‪1433/10/29‬ه ـ وبرفقهــا قــرار املالحظــة الصــادر‬\n‫مــن الدائــرة اخلامســة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n‫بالريــاض برقــم ‪ 33428380‬يف ‪1433/10/16‬ه ـ ونــص احلاجــة منــه (‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫لوحــظ مــا يلــي‪1 :‬ـ لــم جنــد أن فضيلتــه حكــم مبــا قــرره مــن إخــاء‬\n‫ســبيل وال بــد مــن ذلــك ‪2‬ـ تصحيــح بعــض األخطــاء الكتابيــة يف الضبــط‬\n‫والصــك) وعليــه فقــد حكمــت بإخــاء ســبيل املدعــى عليــه مــن هــذه‬\n‫الدعــوى علمــا أن لفظــة احلكــم ســقطت ســهوا مــن الكاتــب وأمــا‬\n‫مــا جــاء يف املالحظــة الثانيــة مــن أخطــاء كتابيــة فقــد مت تعديلهــا يف‬\n‫الصــك وأمــا الضبــط فيتعــذر ذلــك لصعوبــة إحضــار أطــراف الدعــوى‬\n‫ومــن قــام بالتوقيــع علــى الضبــوط وبذلــك مت إكمــال الــازم حيــال‬\n‫مالحظــة أصحــاب الفضيلــة وأمــرت بإحلــاق ذلــك علــى صــك احلكــم‬\n‫وســجله وبــاهلل التوفيــق‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                 ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 3346027‬وتاريــخ ‪1433/01/17‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33118373‬وتاريــخ ‪1433/01/17‬ه ـ ففــي‬\n\n\n                                                                                    ‫‪18‬‬\n\f     ‫يــوم الســبت املوافــق‪ 1434/01/10‬ه ـ حيــث عــادت املعاملــة مــن‬\n     ‫محكمــة االســتئناف مبوجــب خطــاب رئيــس محكمــة االســتئناف رقــم‬\n     ‫‪ 331753042‬يف ‪1433/10/29‬ه ـ وبرفقهــا قــرار املالحظــة الصــادر‬\n     ‫مــن الدائــرة اخلامســة لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف‬\n     ‫بالريــاض برقــم ‪ 33471201‬يف ‪1433/12/01‬ه ـ ونــص احلاجــة منــه (‬\n     ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n     ‫لوحــظ أنــه ورد يف الالئحــة االعتراضيــة املقدمــة مــن املدعــي وكالــة‬\n     ‫واملقيــدة بقيــد احملكمــة رقــم ‪ 331625845‬يف ‪1433/8/28‬ه ـ أن‬\n     ‫املعاملــة بــن املدعــي واملدعــى عليــه عبــارة عــن جتــارة علــى أن يقــوم‬\n     ‫املدعــى عليــه بجلــب بضائــع مــن اإلمــارات ولكــن لــم يجلــب مــا اتفقــا‬\n     ‫عليــه ‪.‬ويطلــب املقابلــة مــع الســجني إلظهــار احلــق ويطعــن يف الشــهود فــا‬\n     ‫بــد مــن عــرض ذلــك علــى الطرفــن ومناقشــة ذلــك وتقريــر مــا يظهــر )‬\n     ‫وعليــه أجيــب أصحــاب الفضيلــة بــأن مــا يدعيــه املدعــي وكالــة مــن أن‬\n     ‫املبلــغ عبــارة عــن جتــارة مخالــف ملــا ورد يف دعــواه وهــذا تناقــض ظاهــر‬\n     ‫ال يقبــل ويــدل علــى عــدم صــدق املدعــي يف دعــواه كمــا أن الدعــوى‬\n     ‫لــو كانــت ابتــداء عالقــة جتاريــة لصــرف النظــر لعــدم االختصــاص‬\n     ‫لكونهــا دعــوى تتعلــق بعمــل جتــاري والدعــاوى يف األعمــال التجاريــة‬\n     ‫مــن اختصــاص القضــاء التجــاري التابــع لديــوان املظالــم وأمــا مــا ورد‬\n     ‫يف القــرار مبــا نصــه (ويطلــب املقابلــة مــع الســجني إلظهــار احلــق ) فهــذه‬\n     ‫اجلملــة غيــر واضحــة فاملدعــى عليــه ليــس ســجينا ويظهــر أنــه مت نقلهــا‬\n     ‫مــن الئحــة املدعــي وكالــة بنصهــا ولذلك إن كان املــراد مقابلة املدعي‬\n     ‫الســجني للمدعــى عليــه فــا أثــر لهــا لعــدم وجــود املبــرر لذلــك كمــا أنــه‬\n     ‫طيلــة جلســات الدعــوى التــي حضــر فيهــا املدعــى عليــه لــم مينــع املدعــي‬\n\n\n‫‪19‬‬\n\f‫مــن احلضــور وأمــا الطعــن يف الشــاهد فقــد مت متكــن املدعــي وكالــة‬\n‫مــن ذلــك كمــا هــو موضــح يف الصفحــة األولــى مــن الصــك وبذلــك‬\n‫متــت اإلجابــة علــى مالحظــة أصحــاب الفضيلــة ولــم يظهــر لــي ســوى مــا‬\n‫حكمــت بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 3346027‬وتاريــخ ‪1433/01/17‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33118373‬وتاريــخ ‪ 1433/01/17‬ه ـ‬\n‫ففــي يــوم األربعــاء املوافــق‪ 1434/03/18‬ه ـ حيــث عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف مبوجــب خطــاب رئيــس محكمــة االســتئناف رقــم‬\n‫‪ 34171616‬يف ‪1434/2/11‬ه ـ وبرفقهــا قــرار املالحظــة الصــادر مــن‬\n‫الدائــرة احلقوقيــة اخلامســة برقــم ‪ 3426962‬يف ‪1434/2/2‬ه ـ ونــص‬\n‫احلاجــة منــه ( لوحــظ أن مــا أجــاب بــه فضيلتــه غيــر مقنــع وال بــد مــن‬\n‫إجابــة وافيــة ملــا ذكــر فعلــى فضيلتــه مالحظــة ذلــك ) وحضــر يف‬\n‫اجللســة املدعــي وجــرى عــرض مالحظــة أصحــاب الفضيلــة عليــه فقــال‬\n‫ال مانــع لــدي مــن مناقشــة املدعــى عليــه هكــذا ذكــر ويف يــوم األحــد‬\n‫املوافــق‪ 1434/04/14‬ه ـ حضــر املدعــي وكالــة ‪ ...‬ولم يحضر الســجني‬\n‫‪ ...‬رغــم طلبــه مبوجــب خطابنــا رقــم ‪ 34731280‬يف ‪1434/3/23‬ه ـ‬\n‫ولــم يحضــر املدعــى عليــه ولذلــك جــرى رفــع اجللســة ويف يــوم األربعــاء‬\n‫املوافــق‪ 1434/04/24‬ه ـ حضــر املدعــي وكالــة ‪ ...‬ولم يحضر الســجني‬\n‫‪ ...‬رغــم طلبــه ولــم يحضــر املدعــى عليــه ولذلــك جــرى رفــع اجللســة ويف‬\n‫يــوم اإلثنــن املوافــق‪ 1434/05/27‬ه ـ حضــر املدعــي وكالــة ‪ ...‬ولــم‬\n\n\n                                                                                   ‫‪20‬‬\n\f     ‫يحضــر الســجني ‪ ...‬رغــم طلبــه وحضــر املدعــى عليــه وكالــة ‪ ...‬ولذلــك‬\n     ‫جــرى رفــع اجللســة وحــدد املوعــد القــادم يــوم الثالثــاء ‪1434/6/13‬ه ـ‬\n     ‫الســاعة ‪ 01 : 00‬ظهــرا ويف يــوم الثالثــاء املوافــق‪ 1434/06/13‬ه ـ‬\n     ‫حضــر املدعــي وكالــة‪ ...‬و الســجني ‪ ...‬مينــي اجلنســية مبوجــب بطاقــة‬\n     ‫نزيــل محكــوم رقــم ‪2/32/249‬س ولــم يحضــر املدعــى عليــه وكالــة‬\n     ‫‪ ...‬وبســؤال املدعــي عمــا ورد يف الئحتــه االعتراضيــة من أســاس التعامل‬\n     ‫فأجــاب قائــا الصحيــح أننــي ســلمت املدعــى عليــه مبلغــا قــدره ثالثمائــة‬\n     ‫وخمســة وتســعون ألــف ريــال مــن أجــل جلــب بضاعــة مــن دولــة اإلمــارات‬\n     ‫العربيــة املتحــدة عبــارة عــن ألعــاب أطفــال مقابــل ربــح لــي قــدره ‪%60‬‬\n     ‫و الباقــي للمدعــى عليــه هكــذا ذكــر وبســؤاله هــل لديــه بينــة علــى‬\n     ‫ذلــك فقــال االتفــاق كان شــفهيا وليــس لــدي أوراق بذلــك ســوى الشــيك‬\n     ‫هكــذا ذكــر ولذلــك ومبــا أن املدعــي ال بينــة لديــه علــى مــا ذكــره مــن‬\n     ‫أن التعامــل عبــارة عــن اتفــاق شــراكة ومبــا أن املدعى عليه حلف اليمني‬\n     ‫ســابقا علــى أن املبلــغ ســداد للديــن فلــم يظهــر لــي ســوى مــا حكمــت بــه‬\n     ‫وأمــرت برفــع املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/13‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلة الشــيخ‬\n     ‫‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة‬\n     ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪3346027‬‬\n     ‫وتاريــخ ‪ 1433/01/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33118373‬وتاريــخ‬\n     ‫‪ 1433/01/17‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/08/07‬ه ـ حيــث‬\n     ‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار املــدون علــى‬\n     ‫ظهــر الصــك واملتضمــن مــا نصــه ( تظهيــرات الدائــرة احلقوقيــة اخلامســة‬\n\n\n‫‪21‬‬\n\f‫مبحكمــة االســتئناف بالريــاض احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا‬\n‫علــى هــذا الصــك رقــم ‪ 34295094‬وتاريــخ ‪1433/4/28‬ه ـ الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة العامــة بالريــاض الشــيخ ‪ ...‬وأصدرنــا‬\n‫القــرار رقــم ‪ 33308896‬وتاريــخ ‪1434/7/11‬ه ـ املتضمــن أنــه لــم يظهــر‬\n‫مــا يوجــب االعتــراض واهلل املوفــق قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n‫قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه)‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم ‪34369251‬‬\n‫وتاريــخ ‪1434/7/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ .../‬املســجل برقــم ‪ ...‬وتاريــخ ‪1433/7/29‬ه ـ اخلــاص‬\n‫بدعــوى‪( .../‬مينــي اجلنســية) ضــد‪ .../‬يف مبلــغ مالــي على الصفــة املوضحة‬\n‫بالصــك واملتضمــن حكــم فضيلتــه كما هو موضح بالصك‪ .‬وباالطالع‬\n‫ـاء‬\n‫علــى مــا أجــاب بــه فضيلتــه وأحلقــه بذيــل الصــك وصــورة ضبطــه و بنـ ً‬\n‫علــى قرارنــا رقــم ‪ 3426962‬وتاريخ‪1434/2/2‬ه ـ لــم يظهــر مــا يوجــب‬\n‫االعتــراض علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪22‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":5,"source_page_end":22,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2f9461a0412b785397d42535c8382590e4d61547eadfe80d2c58e483f8c8d412","normalized_text_hash":"dfae6e8cf90c5882c34890d0acc85dfa606842213016e7f302a0d5c03dcbf733","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p5-34295094"},{"id":"07ed1e04-7b0e-5294-8dc8-a91b986e1fec","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -احلكم على املدعى عليها مبوجب إقرارها -تخلف املدعى عليها عن احلضور بعد جوابها عن الدعوى -إلزام املدعى عليها بسداد ما تبقى من قيمة القرض .","document_number":"3427303","case_number":"2390","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض واملكلف من قبله","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/2","year":"1434","subject":"قرض -احلكم على املدعى عليها مبوجب إقرارها -تخلف املدعى عليها عن احلضور بعد جوابها عن الدعوى -إلزام املدعى عليها بسداد ما تبقى من قيمة القرض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/2 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3427303 :‬‬\n                             ‫َر ْق ُم الدعوى‪2390 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34207628‬تاريخه‪1434/5/6 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬احلكــم علــى املدعــى عليهــا مبوجــب إقرارهــا ‪ -‬تخلــف املدعــى‬\n     ‫عليهــا عــن احلضــور بعــد جوابهــا عــن الدعــوى ‪ -‬إلــزام املدعــى عليهــا‬\n                                         ‫بســداد مــا تبقــى مــن قيمــة القــرض ‪.‬‬\n\n\n\n\n                              ‫قوله تعالى‪ ( :‬يا أيها الذين آمنو أوفوا بالعقود ) ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي أصالــة ووكالــة عــن بقيــة ورثــه والــده جتــاه املدعــى عليهــا‬\n     ‫بــأن مورثهــم أقرضهــا قرضــة حســنة قدرهــا ثالثــة و ثمانــون ألــف ريــال‪،‬‬\n     ‫وأن املدعــى عليهــا ســددت اثنــن وثالثــن ألــف ريــال و املتبقــي واحــد‬\n     ‫وخمســون ألــف ريــال ‪ ،‬طلــب إلــزام املدعــى عليهــا بســداد املبلــغ املتبقــي‪،‬‬\n     ‫أقــرت املدعــى عليهــا بالدعــوى ‪ ،‬رفعــت اجللســة إلحضــار وكاالت عــن‬\n     ‫بقيــة الورثــة ‪ ،‬يف اجللســة احملــددة حضــر وكيــل آخــر وادعــى مبثــل مــا‬\n     ‫ادعــى بــه األول ولــم حتضــر املدعــى عليهــا ‪ ،‬صــدر احلكم بإلــزام املدعى‬\n     ‫عليهــا بدفــع املبلــغ املدعــى بــه و يعــد احلكــم يف حقهــا حضوريـاً‪ ،‬صــدق‬\n                                                     ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫‪23‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬املــازم القضائــي لــدى فضيلــة الشــيخ‬\n‫‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض واملكلــف مــن قبلــه وبنــاء‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫برقــم ‪ 2390‬واملقيــدة باحملكمــة برقــم ‪ 329757‬ففــي يــوم األحــد‬\n‫املوافق ‪1432/12/24‬هـ افتتحت اجللسة الساعة ‪ 11 : 17‬وفيها حضر‬\n‫املدعــي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬باألصالة عن‬\n‫نفســه وبصفتــه وكيــا مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب الريــاض برقــم ‪ 56902‬يف ‪1432/7/2‬ه ـ اجللــد ‪5020‬‬\n‫عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬واملخــول لــه فيهــا‬\n‫باملطالبــة واملرافعــة واملخاصمــة واإلقــرار واإلنــكار والصلــح هــذا ولــم‬\n‫حتضــر املدعــى عليهــا ‪...‬أو مــن ينــوب عنهــا وقــد جــرى الكتابــة إلبــاغ‬\n‫املدعــى عليهــا يف مقــر عملهــا فوردنــا ورقــة تبليــغ احلضــور واملتضمنــة‬\n‫بــأن محضــر اخلصــوم ‪ ...‬أفــاد بأنــه مت اخلــروج يف يــوم األحــد‪7/10‬‬\n‫الســاعة احلاديــة عشــرة صباحــا ومقابلــة مديــر املركــز حيــث أفــاد‬\n‫بــأن املدعــى عليهــا منتدبــة ملــدة شــهر وســوف تعــود بعــد أســبوعني مــن‬\n‫اآلن مديــر املركــز الصحــي ‪ ......‬وتوقيعــه لــذا فقــد جــرى رفــع اجللســة‬\n‫لطلــب املدعــى عليهــا حتــى يــوم األربعــاء املوافق‪1433/4/28‬ه ـ الســاعة‬\n‫العاشــرة صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1432/12/24‬ه ـ احلمــد هلل وحــده وبعــد‬\n‫فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالرياض‪/‬املســاعد‬\n\n                                                                                     ‫‪24‬‬\n\f     ‫برقــم ‪ 2390‬املقيــدة باحملكمــة برقــم ‪ 329757‬ففــي يــوم الثالثــاء‬\n     ‫املوافــق‪ 1433/08/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 11‬وفيهــا حضــر‬\n     ‫املدعــي أصالــة ووكالــة ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪...‬وحضــرت‬\n     ‫حلضــوره املدعــى عليهــا ‪ ...‬ســعودية بالســجل املدنــي رقــم ‪...‬برفقــة ابنهــا‬\n     ‫‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬وبســؤال املدعــي عــن دعــواه أجــاب‬\n     ‫قائــا لقــد اقترضــت املدعــى عليهــا مــن والــدي عــام ‪1423‬ه ـ مبلغــا‬\n     ‫وقــدره ثالثــة وثمانــون ألــف ريــال ثــم تــويف والدنــا رحمــه اهلل بتاريــخ‬\n     ‫‪1431/08/28‬هـ وانحصر إرثه يف أوالده ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ويف زوجتيه‬\n     ‫‪...‬و‪...‬وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة‬\n     ‫برقــم ‪ 315613671125310303‬يف ‪1431/09/14‬ه ـ وقــد ســددت‬\n     ‫منــه املدعــى عليهــا مبلغــا وقــدره اثنــان وثالثــون ألفــا وبقــي يف ذمتهــا مــن‬\n     ‫كامــل ذلــك القــرض مبلغــا وقــدره واحــد وخمســون ألــف ريــال ونظــرا‬\n     ‫إلــى حلــول كامــل املبلــغ املتبقــي مــن ذلــك القــرض فإنــي أطلــب احلكــم‬\n     ‫علــى املدعــى عليهــا احلاضــرة بــأن تدفــع لــي مبلغا وقدره واحد وخمســون‬\n     ‫ألــف ريــال هــذه دعــواي هــذا وقــد جــرى منــا اإلطــاع علــى أصــل صــك‬\n     ‫حصــر ورثــة والــده فوجدتــه كمــا ذكــر وبســؤاله عــن بقيــة ورثــة والــده‬\n     ‫أجــاب قائــا ســوف أحضــر يف اجللســة القادمــة وكاالت عنهــم وبعــرض‬\n     ‫دعــوى املدعــي علــى املدعــى عليهــا احلاضــرة أجابــت قائلــة مــا ذكــره‬\n     ‫املدعــي أصالــة ووكالــة يف دعــواه كلــه صحيــح فقــد اقترضــت مــن‬\n     ‫والدهــم ذلــك املبلــغ وســددت جــزء منــه واملتبقــي يف ذمتــي مــن كامــل‬\n     ‫ذلــك القــرض هــو واحــد وخمســون ألــف ريــال جميعها حالة وأنا مســتعدة‬\n     ‫بالســداد هكــذا أجابــت ورفعــت اجللســة بعــد إفهــام املدعــي بإحضــار‬\n     ‫وكالــة عــن جميــع ورثــة والــده تخولــه املطالبــة واملرافعــة واملدافعــة‬\n\n\n‫‪25‬‬\n\f‫واإلقــرار واإلنــكار وقبــول احلكــم واإلعتــراض عليــه واإلســتالم وبعــد‬\n‫إفهــام الطرفــن باحلضــور يف يــوم األحــد املوافــق ‪1434/01/25‬ه ـ‬\n‫الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/20‬ه ـ‬\n‫احلمد هلل وحده وبعد فلدي أنا ‪...‬القاضي يف احملكمة العامة بالرياض‬\n‫ففــي يــوم األحــد املوافــق‪ 1434/01/25‬ه ـ افتتحت اجللســة الســاعة ‪: 40‬‬\n‫‪ 9‬وفيهــا حضــر ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪...‬باألصالــة عــن نفســه‬\n‫وبالوكالــة عــن ‪ ...‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب الريــاض برقــم ‪ 4949‬يف ‪1433/01/17‬ه ـ واملجعــول‬\n‫للوكيــل فيهــا حــق املطالبــة وإقامة الدعــاوى ودفعها واملرافعــة واملدافعة‬\n‫والصلــح وقبــول احلكــم واإلعتــراض عليــه واإلســتالم وبالوكالــة أيضــا‬\n‫عــن ‪ ...‬و‪...‬و‪ ......‬و‪...‬و‪...‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 38912‬يف ‪1432/05/07‬ه ـ‬\n‫واملجعــول للوكيــل فيــه حــق املطالبــة واملخاصمة وســماع الدعاوى والرد‬\n‫عليهــا وإقامــة البينــة وقبــول احلكــم واإلعتــراض عليــه واإلســتالم هــذا‬\n‫ولــم حتضــر املدعــى عليهــا ‪...‬رغــم تبلغهــا يف اجللســة املاضيــة وتوقيعهــا‬\n‫علــى ذلــك وبســؤال املدعــي أصالــة ووكالــة عمــا لديــه أجــاب قائــا‬\n‫أصالــة عــن نفســي وبصفتــي وكيــا عــن بقيــة ورثــة والــدي فإنــي ادعــي‬\n‫مبــا ادعــى بــه أخــي وموكلــي ‪ ...‬يف اجللســة املاضيــة هكــذا أجــاب فبنــاء‬\n‫علــى مــا تقــدم مــن املدعــوى واإلجابــة وملصادقــة املدعــى عليهــا علــى مــا‬\n‫جــاء يف الدعــوى واســتعدادها بالســداد وحللــول املبلــغ املدعــى بــه وبعــد‬\n‫اإلطــاع علــى أصــل صــك حصــر الورثــة وأصــل الوكالتــن ولكــون‬\n‫املدعــي أصالــة ووكالــة مخــوال يف وكالتــه باإلســتالم ولقولــه تعالــى (‬\n\n\n                                                                                     ‫‪26‬‬\n\f     ‫ياأيهــا الذيــن أمنــوا أوفــوا بالعقــود) وجلميــع مــا ســبق فقــد حكمــت علــى‬\n     ‫املدعــى عليهــا ‪ ...‬بــأن تدفــع للمدعــي أصالــة ووكالــة ‪...‬املبلــغ املدعــى بــه‬\n     ‫وقــدره واحــد وخمســون ألــف ريــال ويعــد هــذا احلكــم حضوريــا يف حــق‬\n     ‫املدعــى عليهــا وبعرضــه علــى املدعــي أصالــة ووكالــة قنــع بــه وســيجري‬\n     ‫تبليــغ املدعــى عليهــا باحلكــم كاملتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/25‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييــز‬\n     ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض على املعاملــة الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامة بالرياض املســاعد برقــم ‪32/9757‬‬\n     ‫وتاريــخ ‪1434/04/27‬ه ـ املرفــق بهــا الصك الصادر من فضيلة القاضي‬\n     ‫باحملكمــة الشــيخ ‪... /‬املســجل برقــم ‪ 3427303‬وتاريــخ ‪1434/2/2‬ه ـ‬\n     ‫اخلــاص بدعــوى ‪ /‬ورثــة ‪ ...‬ضــد‪... /‬وبدراســة الصــك وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة لــم يظهــر لألكثريــة مــا يوجــب املالحظــة واهلل املوفــق‬\n                                ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":23,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e05aabee198329aae93ee126d7c8aac24aa738a112912b96979e4bd24a98ec64","normalized_text_hash":"3d1a8caf0c0b00cc089aba8617da38323c6e6fa85982e49be813e87bd75547a0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p23-3427303"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

